    "                    curve_rows.append({'prior':prior,'cost':cost,'intended_fraction':float(fraction),'threshold':threshold_f,**measure(frame,mask,cost=cost)})\n",
    '            previous = np.zeros(len(frame),dtype=bool)\n',
