    'ATTRIBUTES = ("income", "ownrent", "marital", "creditcd", "prizm_social_one")\n',
    'BINARY_CODINGS = {"creditcd": {"N": 0, "Y": 1}, "ownrent": {"R": 0, "O": 1}}\n',
    'MISSING_TARGET_TOKENS = {"", "NAN", "NONE", "NULL", "<NA>", MISSING}\n',
    'REQUIRED_SELECTED = ("Customer_ID", "y", "p_s", "p_d", "value", "weight",\n',
    '                     "selected_risk", "selected_bayes")\n',
    'PROTOCOL = "C-20261028-fold-local-income-v1"\n',
    'PROXY_PARAMS = {\n',
