    '    "max_depth": 4, "num_leaves": 15, "min_child_samples": 200,\n',
    '    "subsample": 0.8, "subsample_freq": 1, "colsample_bytree": 0.8,\n',
    '    "reg_alpha": 1.0, "reg_lambda": 10.0, "class_weight": "balanced",\n',
    '    "n_jobs": THREADS, "random_state": SEED, "verbosity": -1,\n',
    '    "deterministic": True, "force_col_wise": True,\n',
    '}\n',
    '\n',
    '\n',
    'def require(condition, message):\n',
    '    if not condition:\n',
    '        raise ValueError(message)\n',
    '\n',
    '\n',
    'def json_safe(value):\n',
    '    if isinstance(value, dict):\n',
    '        return {str(k): json_safe(v) for k, v in value.items()}\n',
    '    if isinstance(value, (list, tuple, np.ndarray)):\n',
    '        return [json_safe(v) for v in value]\n',
    '    if isinstance(value, np.generic):\n',
    '        return json_safe(value.item())\n',
    '    if isinstance(value, Path):\n',
    '        return str(value.resolve())\n',
    '    if value is pd.NA:\n',
    '        return None\n',
    '    if isinstance(value, float) and not np.isfinite(value):\n',
    '        return None\n',
    '    return value\n',
    '\n',
    '\n',
    'def write_json(path, value):\n',
    '    path.write_text(json.dumps(json_safe(value), indent=2, allow_nan=False),\n',
    '                    encoding="utf-8")\n',
    '\n',
    '\n',
    'def stable_seed(*parts):\n',
    '    digest = hashlib.sha256("|".join(map(str, parts)).encode()).digest()\n',
    '    return (SEED + int.from_bytes(digest[:4], "little")) % (2**32)\n',
    '\n',
    '\n',
    'def sha256_file(path):\n',
    '    digest = hashlib.sha256()\n',
