    '\n',
    '\n',
    'def verified_income(series):\n',
    '    normalized = normalize_category(series)\n',
    '    numeric = pd.to_numeric(normalized.mask(normalized.eq(MISSING)), errors="raise")\n',
    '    known = numeric.dropna().to_numpy(dtype=float)\n',
