    '    require(((known >= 1) & (known <= 9) & (known == np.floor(known))).all(),\n',
    '            "Verify the income schema: expected ordinal codes 1-9, not currency.")\n',
    '    return numeric.astype(float)\n',
    '\n',
    '\n',
    'def group_columns(data):\n',
    '    result = pd.DataFrame(index=data.index)\n',
    '    income = verified_income(data["income"])\n',
    '    result["income"] = income.map(lambda x: MISSING if pd.isna(x) else str(int(x)))\n',
    '    for attribute in ATTRIBUTES[1:]:\n',
    '        result[attribute] = normalize_category(data[attribute])\n',
    '    return result\n',
    '\n',
    '\n',
    'def reference_groups(data, splits):\n',
    '    # The group vocabulary is fixed from the original 75k, never from test.\n',
    '    indices = np.concatenate([splits["train"], splits["validation"]])\n',
