    '    require(text.isin(coding).all(), f"{name} must contain explicit booleans or 0/1.")\n',
    '    return text.map(coding).astype(bool)\n',
    '\n',
    '\n',
    'def load_selected(data, splits, partition):\n',
    '    path = WORK / f"a_selected_{partition}.csv"\n',
    '    require(path.exists(), f"Workstream A must first produce {path}.")\n',
    '    frame = pd.read_csv(path)\n',
    '    require(set(REQUIRED_SELECTED).issubset(frame),\n',
    '            f"{path} must contain {\', \'.join(REQUIRED_SELECTED)}.")\n',
    '    require(not frame["Customer_ID"].isna().any() and frame["Customer_ID"].is_unique,\n',
    '            "Selected-policy Customer_ID must be complete and unique.")\n',
    '    split_name = "calibration_policy" if partition == "calibration" else "test"\n',
    '    expected = data.iloc[splits[split_name]].set_index("Customer_ID")\n',
    '    require(set(frame["Customer_ID"]) == set(expected.index),\n',
    '            f"{path} must cover exactly the original {split_name} partition.")\n',
    '    frame = frame.set_index("Customer_ID").loc[expected.index].reset_index()\n',
    '    for column in ("y", "p_s", "p_d", "value", "weight"):\n',
    '        frame[column] = pd.to_numeric(frame[column], errors="raise")\n',
    '        require(np.isfinite(frame[column]).all(), f"{column} must be finite.")\n',
    '    require(frame["y"].isin([0, 1]).all(), "y must be explicitly coded 0/1.")\n',
    '    require(np.array_equal(frame["y"].to_numpy(), expected["churn"].to_numpy()),\n',
    '            "A\'s outcomes do not match the immutable source partition.")\n',
    '    for probability in ("p_s", "p_d"):\n',
    '        require(frame[probability].between(0, 1).all(), f"Invalid {probability}.")\n',
    '    require(frame["value"].ge(0).all() and frame["weight"].gt(0).all(),\n',
    '            "Policy value must be nonnegative and deployment weights positive.")\n',
    '    for policy in ("risk", "bayes"):\n',
    '        frame[f"selected_{policy}"] = parse_selection(frame[f"selected_{policy}"], policy)\n',
    '    if "partition" in frame:\n',
    '        require(frame["partition"].isin([partition, split_name]).all(),\n',
    '                "A\'s partition declaration does not match this CLI partition.")\n',
    '    w, y = frame["weight"].to_numpy(), frame["y"].to_numpy()\n',
    '    require(np.isclose(np.dot(w, y) / w.sum(), DEPLOYMENT_PRIOR, atol=1e-7),\n',
    '            "Expected the declared 2% deployment scenario in A\'s weights.")\n',
    '    for label in (0, 1):\n',
    '        class_weights = w[y == label]\n',
    '        require(len(class_weights) > 0 and np.allclose(class_weights, class_weights[0]),\n',
    '                "Expected outcome-stratified, constant-within-class deployment weights.")\n',
    '    for attribute in ATTRIBUTES:\n',
    '        frame[attribute] = expected[attribute].to_numpy()\n',
    '    frame["raw_totmrc_Mean"] = expected["totmrc_Mean"].to_numpy()\n',
    '    return frame, path\n',
    '\n',
    '\n',
    'def ratio(numerator, denominator):\n',
    '    return float(numerator / denominator) if denominator > 0 else np.nan\n',
    '\n',
    '\n',
    'def performance(y, ps, pd_, value, weights, risk, bayes, model_selected):\n',
    '    result = {}\n',
    '    for regime, w, probability in (("sample", np.ones(len(y)), ps),\n',
    '                                    ("deployment", weights, pd_)):\n',
    '        positive, negative = w * y, w * (1 - y)\n',
    '        total, pos, neg = w.sum(), positive.sum(), negative.sum()\n',
    '        result[(regime, "model", "calibration_observed_expected")] = ratio(\n',
    '            pos, np.dot(w, probability))\n',
    '        policies = {"model": model_selected, "risk": risk, "bayes": bayes}\n',
    '        for policy, selected in policies.items():\n',
    '            result[(regime, policy, "tpr")] = ratio(np.dot(positive, selected), pos)\n',
    '            result[(regime, policy, "fpr")] = ratio(np.dot(negative, selected), neg)\n',
    '            result[(regime, policy, "selection_rate")] = ratio(np.dot(w, selected), total)\n',
    '            if policy != "model":\n',
    '                result[(regime, policy, "precision")] = ratio(\n',
    '                    np.dot(positive, selected), np.dot(w, selected))\n',
    '                result[(regime, policy, "churn_value_capture")] = ratio(\n',
    '                    np.dot(positive * value, selected), np.dot(positive, value))\n',
    '        for metric in ("tpr", "fpr", "selection_rate", "precision", "churn_value_capture"):\n',
    '            result[(regime, "bayes_minus_risk", metric)] = (\n',
    '                result[(regime, "bayes", metric)] - result[(regime, "risk", metric)])\n',
    '    return result\n',
    '\n',
    '\n',
    'def suppression_reason(metric, policy, counts):\n',
    '    reasons = []\n',
    '    if counts["n"] < MIN_N:\n',
    '        reasons.append("n<200")\n',
    '    if metric in ("tpr", "calibration_observed_expected", "churn_value_capture"):\n',
    '        if counts["n_positive"] < MIN_CLASS:\n',
    '            reasons.append("positive_class<30")\n',
    '    if metric == "fpr" and counts["n_negative"] < MIN_CLASS:\n',
    '        reasons.append("negative_class<30")\n',
    '    if metric == "precision":\n',
    '        policies = ("risk", "bayes") if policy == "bayes_minus_risk" else (policy,)\n',
    '        for selected_policy in policies:\n',
    '            if counts[f"n_selected_{selected_policy}"] < MIN_N:\n',
    '                reasons.append(f"{selected_policy}_selected_n<200")\n',
    '            if counts[f"n_selected_positive_{selected_policy}"] < MIN_CLASS:\n',
    '                reasons.append(f"{selected_policy}_selected_positive<30")\n',
    '            if counts[f"n_selected_negative_{selected_policy}"] < MIN_CLASS:\n',
    '                reasons.append(f"{selected_policy}_selected_negative<30")\n',
    '    return ";".join(reasons)\n',
    '\n',
    '\n',
    'def percentile_ci(values):\n',
    '    finite = np.asarray(values)[np.isfinite(values)]\n',
    '    if len(finite) < int(0.9 * BOOTSTRAPS):\n',
    '        return np.nan, np.nan, len(finite)\n',
    '    lower, upper = np.quantile(finite, [0.025, 0.975])\n',
    '    return float(lower), float(upper), len(finite)\n',
    '\n',
    '\n',
    'def subgroup_audit(frame, universe, partition):\n',
    '    groups = group_columns(frame)\n',
    '    records = []\n',
    '    for attribute in ATTRIBUTES:\n',
    '        observed = set(groups[attribute])\n',
    '        # New categories are reported, not merged away or used for decisions.\n',
    '        for group in sorted(set(universe[attribute]) | observed):\n',
    '            subset = frame.loc[groups[attribute].eq(group)]\n',
    '            y = subset["y"].to_numpy(dtype=int)\n',
    '            ps, pd_ = subset["p_s"].to_numpy(), subset["p_d"].to_numpy()\n',
    '            value, w = subset["value"].to_numpy(), subset["weight"].to_numpy()\n',
    '            risk = subset["selected_risk"].to_numpy(dtype=bool)\n',
    '            bayes = subset["selected_bayes"].to_numpy(dtype=bool)\n',
    '            model = ps >= SAMPLE_THRESHOLD\n',
    '            counts = {"n": len(y), "n_positive": int(y.sum()),\n',
    '                      "n_negative": int((1 - y).sum()),\n',
    '                      "deployment_mass": float(w.sum()),\n',
    '                      "deployment_positive_mass": float(np.dot(w, y)),\n',
    '                      "deployment_negative_mass": float(np.dot(w, 1 - y)),\n',
    '                      "sample_expected_churn_mass": float(ps.sum()),\n',
    '                      "deployment_expected_churn_mass": float(np.dot(w, pd_))}\n',
    '            for policy, selected in (("risk", risk), ("bayes", bayes), ("model", model)):\n',
    '                counts.update({\n',
    '                    f"n_selected_{policy}": int(selected.sum()),\n',
    '                    f"n_selected_positive_{policy}": int(np.dot(y, selected)),\n',
    '                    f"n_selected_negative_{policy}": int(np.dot(1 - y, selected)),\n',
    '                    f"deployment_selected_mass_{policy}": float(np.dot(w, selected)),\n',
    '                    f"deployment_selected_positive_mass_{policy}": float(np.dot(w * y, selected)),\n',
    '                    f"deployment_selected_negative_mass_{policy}": float(np.dot(w * (1 - y), selected)),\n',
    '                })\n',
    '            estimates = performance(y, ps, pd_, value, w, risk, bayes, model)\n',
    '            keys = list(estimates)\n',
    '            draws = np.full((BOOTSTRAPS if len(y) else 0, len(keys)), np.nan)\n',
    '            if len(y):\n',
    '                rng = np.random.default_rng(stable_seed(partition, attribute, group))\n',
    '                for replicate in range(BOOTSTRAPS):\n',
    '                    sample = rng.integers(0, len(y), len(y))\n',
    '                    metrics = performance(y[sample], ps[sample], pd_[sample], value[sample],\n',
    '                                          w[sample], risk[sample], bayes[sample], model[sample])\n',
    '                    draws[replicate] = [metrics[key] for key in keys]\n',
    '            for column, (regime, policy, metric) in enumerate(keys):\n',
    '                reason = suppression_reason(metric, policy, counts)\n',
    '                lower, upper, valid = percentile_ci(draws[:, column])\n',
    '                if not reason and (not np.isfinite(estimates[(regime, policy, metric)])\n',
    '                                   or not np.isfinite(lower)):\n',
    '                    reason = "zero_denominator_or_insufficient_finite_bootstraps"\n',
    '                suppressed = bool(reason)\n',
    '                records.append({\n',
    '                    "partition": partition, "attribute": attribute, "group": group,\n',
    '                    "is_missing_group": group == MISSING,\n',
    '                    "absent_group": not len(y), "unseen_in_train_validation": group not in universe[attribute],\n',
    '                    "regime": regime, "policy": policy, "metric": metric,\n',
    '                    "estimate": np.nan if suppressed else estimates[(regime, policy, metric)],\n',
    '                    "ci_low": np.nan if suppressed else lower,\n',
    '                    "ci_high": np.nan if suppressed else upper,\n',
    '                    "suppressed": suppressed, "suppression_reason": reason,\n',
    '                    "small_n": counts["n"] < MIN_N,\n',
    '                    "small_positive_class": counts["n_positive"] < MIN_CLASS,\n',
    '                    "small_negative_class": counts["n_negative"] < MIN_CLASS,\n',
    '                    "bootstrap_replicates": len(draws), "finite_bootstrap_replicates": valid,\n',
    '                    "sample_model_threshold": SAMPLE_THRESHOLD,\n',
    '                    "deployment_model_threshold_equivalent": float(common.shift(\n',
    '                        SAMPLE_THRESHOLD, prior=DEPLOYMENT_PRIOR)),\n',
    '                    **counts,\n',
    '                })\n',
    '    return pd.DataFrame(records)\n',
    '\n',
    '\n',
    'def weighted_quantile(values, weights, quantile):\n',
    '    # Inverse empirical CDF for both unit and deployment weights; no interpolation.\n',
    '    if not len(values) or weights.sum() <= 0:\n',
    '        return np.nan\n',
    '    order = np.argsort(values, kind="stable")\n',
    '    cumulative = np.cumsum(weights[order])\n',
    '    position = min(np.searchsorted(cumulative, quantile * cumulative[-1], side="left"),\n',
    '                   len(order) - 1)\n',
    '    return float(values[order[position]])\n',
    '\n',
    '\n',
    'def distribution(values, w, selected, income=False):\n',
    '    finite = np.isfinite(values)\n',
    '    valid = selected & finite\n',
    '    v, mass = values[valid], w[valid]\n',
    '    result = {"selected_mass": float(w[selected].sum()),\n',
    '              "observed_mass": float(mass.sum()),\n',
    '              "missing_mass": float(w[selected & ~finite].sum()),\n',
    '              "mean_ordinal_code" if income else "mean": ratio(np.dot(mass, v), mass.sum()),\n',
    '              "minimum": float(v.min()) if len(v) else np.nan,\n',
    '              "maximum": float(v.max()) if len(v) else np.nan}\n',
    '    if not income:\n',
    '        result["negative_mass"] = float(w[selected & finite & (values < 0)].sum())\n',
    '    for q in (0.1, 0.25, 0.5, 0.75, 0.9, 0.99):\n',
    '        result[f"p{int(q * 100)}"] = weighted_quantile(v, mass, q)\n',
    '    return result\n',
    '\n',
    '\n',
    'def equity_audit(frame, universe, partition):\n',
    '    groups = group_columns(frame)\n',
    '    records = []\n',
    '    all_rows = np.ones(len(frame), dtype=bool)\n',
    '    policies = {"population": all_rows,\n',
    '                "risk": frame["selected_risk"].to_numpy(dtype=bool),\n',
    '                "bayes": frame["selected_bayes"].to_numpy(dtype=bool)}\n',
    '    for regime, w in (("sample", np.ones(len(frame))),\n',
    '                      ("deployment", frame["weight"].to_numpy())):\n',
    '        for attribute in ATTRIBUTES:\n',
    '            for group in sorted(set(universe[attribute]) | set(groups[attribute])):\n',
    '                member = groups[attribute].eq(group).to_numpy()\n',
    '                group_mass = w[member].sum()\n',
    '                measures = {name: {\n',
    '                    "count": float(w[member & selected].sum()),\n',
    '                    "share_of_selected": ratio(w[member & selected].sum(), w[selected].sum()),\n',
    '                    "within_group_selection_rate": ratio(w[member & selected].sum(), group_mass),\n',
    '                } for name, selected in policies.items()}\n',
    '                for metric in ("count", "share_of_selected", "within_group_selection_rate"):\n',
    '                    row = {name: measures[name][metric] for name in policies}\n',
    '                    records.append({\n',
    '                        "partition": partition, "section": "category_mix",\n',
    '                        "attribute": attribute, "group": group, "regime": regime,\n',
    '                        "metric": metric, **row,\n',
    '                        "bayes_minus_risk": row["bayes"] - row["risk"],\n',
    '                        "n_population": int(member.sum()),\n',
    '                        "n_risk": int((member & policies["risk"]).sum()),\n',
    '                        "n_bayes": int((member & policies["bayes"]).sum()),\n',
    '                        "population_mass": float(group_mass),\n',
    '                        "risk_total_mass": float(w[policies["risk"]].sum()),\n',
    '                        "bayes_total_mass": float(w[policies["bayes"]].sum()),\n',
    '                        "small_n": int(member.sum()) < MIN_N,\n',
    '                        "is_missing_group": group == MISSING,\n',
    '                        "absent_group": not member.any(),\n',
    '                        "unseen_in_train_validation": group not in universe[attribute],\n',
    '                        "interpretation": "exact descriptive mix, not an inferential quality estimate",\n',
    '                    })\n',
    '        for column in ("income", "value", "raw_totmrc_Mean"):\n',
    '            values = (verified_income(frame[column]).to_numpy() if column == "income"\n',
    '                      else pd.to_numeric(frame[column], errors="raise").to_numpy(dtype=float))\n',
    '            measures = {name: distribution(values, w, selected, income=column == "income")\n',
    '                        for name, selected in policies.items()}\n',
    '            for metric in measures["population"]:\n',
    '                row = {name: measures[name][metric] for name in policies}\n',
    '                records.append({\n',
    '                    "partition": partition, "section": "income_distribution" if column == "income" else "bill_distribution",\n',
    '                    "attribute": column, "group": "__ALL__", "regime": regime,\n',
    '                    "metric": metric, **row, "bayes_minus_risk": row["bayes"] - row["risk"],\n',
    '                    "n_population": len(frame), "n_risk": int(policies["risk"].sum()),\n',
    '                    "n_bayes": int(policies["bayes"].sum()),\n',
    '                    "population_mass": float(w.sum()),\n',
    '                    "risk_total_mass": float(w[policies["risk"]].sum()),\n',
    '                    "bayes_total_mass": float(w[policies["bayes"]].sum()),\n',
    '                    "interpretation": ("income is an ordinal 1-9 code, not currency; code means are descriptive"\n',
    '                                       if column == "income" else\n',
    '                                       "A\'s value is training-capped/imputed; raw_totmrc_Mean is unimputed source billing"),\n',
    '                })\n',
    '    return pd.DataFrame(records)\n',
    '\n',
    '\n',
    'def operational_matrix(non_test):\n',
    '    """Reproduce the frozen row-local 87 features without fitting a vocabulary."""\n',
    '    manifest_path = ROOT / "v1_frozen/analysis_outputs/feature_manifest.json"\n',
    '    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n',
    '    names, cats = manifest["features"], manifest["categorical_features"]\n',
    '    require(len(names) == len(set(names)) == 87, "Expected exactly 87 frozen operational features.")\n',
    '    forbidden = set(manifest["excluded_features"]) | set(ATTRIBUTES) | {"asl_flag", "area"}\n',
    '    require(not forbidden.intersection(names), "Sensitive targets are prohibited proxy inputs.")\n',
    '    X = non_test[[name for name in names if name in non_test]].copy()\n',
    '    X["equipment_age_invalid"] = (X["eqpdays"] < 0).astype("int8")\n',
    '    X["eqpdays"] = X["eqpdays"].where(X["eqpdays"] >= 0)\n',
    '    for name, numerator, denominator in (\n',
    '        ("usage_recent_to_lifetime", "avg3mou", "avgmou"),\n',
    '        ("usage_three_to_six_months", "avg3mou", "avg6mou"),\n',
    '        ("revenue_recent_to_lifetime", "avg3rev", "avgrev"),\n',
    '        ("revenue_three_to_six_months", "avg3rev", "avg6rev"),\n',
    '        ("overage_charge_share", "ovrrev_Mean", "rev_Mean"),\n',
    '        ("recurring_charge_share", "totmrc_Mean", "rev_Mean"),\n',
    '        ("failed_call_index", "drop_blk_Mean", "attempt_Mean"),\n',
    '        ("usage_change_scaled", "change_mou", "avg3mou"),\n',
    '        ("revenue_change_scaled", "change_rev", "avg3rev"),\n',
    '    ):\n',
    '        X[name] = X[numerator] / X[denominator].clip(lower=1)\n',
    '    X["care_calls_per_100_attempts"] = 100 * X["custcare_Mean"] / X["attempt_Mean"].clip(lower=1)\n',
    '    X["equipment_age_to_tenure"] = X["eqpdays"] / (30.4375 * X["months"].clip(lower=1))\n',
    '    X["inactive_household_lines"] = (X["uniqsubs"] - X["actvsubs"]).clip(lower=0)\n',
    '    require(set(X) == set(names), "Frozen operational feature contract has changed.")\n',
    '    X = X[names]\n',
    '    require(set(cats).issubset(X), "Invalid frozen categorical feature manifest.")\n',
    '    for column in cats:\n',
    '        X[column] = X[column].fillna(MISSING).astype(str)\n',
    '    numeric = [column for column in names if column not in cats]\n',
    '    X[numeric] = X[numeric].replace([np.inf, -np.inf], np.nan).astype("float32")\n',
    '    return X, cats, manifest\n',
    '\n',
    '\n',
    'def proxy_inputs(data, splits):\n',
    '    indices = np.concatenate([splits["train"], splits["validation"]])\n',
    '    require(len(indices) == 75000 and not np.intersect1d(indices, splits["test"]).size,\n',
    '            "Proxy CV must use only the original 60k train + 15k validation.")\n',
    '    non_test = data.iloc[indices].reset_index(drop=True)\n',
    '    X, cats, manifest = operational_matrix(non_test)\n',
    '    targets, descriptions = {}, {}\n',
    '    for target, coding in BINARY_CODINGS.items():\n',
    '        normalized = normalize_category(non_test[target])\n',
    '        counts = normalized.value_counts(dropna=False).to_dict()\n',
    '        observed = set(normalized) - {MISSING}\n',
    '        require(observed == set(coding),\n',
    '                f"Verify {target} before fitting: observed {sorted(observed)}, expected {sorted(coding)}.")\n',
    '        labels = normalized.map(coding).astype(float)\n',
    '        require(labels.notna().sum() >= 5 * MIN_N, f"Too few observed {target} targets for five-fold CV.")\n',
    '        targets[target] = labels\n',
    '        descriptions[target] = {"observed_values": counts, "coding": coding,\n',
    '                                "label_definition": "credit-card present (Y=1)" if target == "creditcd" else "home owner (O=1)",\n',
    '                                "missing_targets_dropped": int(labels.isna().sum())}\n',
    '    income = verified_income(non_test["income"])\n',
    '    train_income = verified_income(data.iloc[splits["train"]]["income"])\n',
    '    require(train_income.notna().any(), "Original 60k train has no observed income.")\n',
    '    reference = float(train_income.dropna().median())\n',
    '    require(income.notna().sum() >= 5 * MIN_N, "Too few observed income labels for five-fold CV.")\n',
    '    targets["income_high"] = income\n',
    '    descriptions["income_high"] = {\n',
    '        "observed_values": normalize_category(non_test["income"]).value_counts(dropna=False).to_dict(),\n',
    '        "coding": {"income>fold_training_median": 1, "income<=fold_training_median": 0},\n',
    '        "label_definition": "high income ordinal code, strictly above the fold-training observed median",\n',
    '        "missing_targets_dropped": int(income.isna().sum()),\n',
    '        "original_60000_train_reference_threshold": reference,\n',
    '        "reference_high_count_train_validation": int(income.gt(reference).sum()),\n',
    '        "reference_low_count_train_validation": int(income.le(reference).sum()),\n',
    '        "reference_threshold_role": "fixed non-test reporting reference only; not the CV target threshold",\n',
    '        "ties": "median ties are low; labels are not forced to 50/50",\n',
    '    }\n',
    '    digest = hashlib.sha256()\n',
    '    digest.update(json.dumps({"protocol": PROTOCOL, "params": PROXY_PARAMS,\n',
    '                              "descriptions": descriptions, "features": manifest},\n',
    '                             sort_keys=True, default=str).encode())\n',
    '    digest.update(pd.util.hash_pandas_object(X, index=False).to_numpy().tobytes())\n',
    '    digest.update(pd.util.hash_pandas_object(non_test[["Customer_ID", "creditcd", "ownrent", "income"]],\n',
    '                                            index=False).to_numpy().tobytes())\n',
    '    digest.update(pd.util.hash_pandas_object(data.iloc[splits["train"]][["Customer_ID", "income"]],\n',
    '                                            index=False).to_numpy().tobytes())\n',
    '    return X, cats, targets, descriptions, digest.hexdigest()\n',
    '\n',
    '\n',
    'def fold_features(X, cats, train, validation):\n',
    '    fitted, held = X.iloc[train].copy(), X.iloc[validation].copy()\n',
    '    unknown_counts = {}\n',
    '    for column in cats:\n',
    '        vocabulary = sorted(fitted[column].unique().tolist())\n',
    '        unknown_counts[column] = int((~held[column].isin(vocabulary)).sum())\n',
    '        fitted[column] = pd.Categorical(fitted[column], categories=vocabulary)\n',
    '        held[column] = pd.Categorical(held[column], categories=vocabulary)\n',
    '    # LightGBM handles numeric NaN natively; no global imputation or label imputation.\n',
    '    return fitted, held, unknown_counts\n',
    '\n',
    '\n',
    'def proxy_bootstrap(y, probability, seed):\n',
    '    rng = np.random.default_rng(seed)\n',
    '    negative, positive = np.flatnonzero(y == 0), np.flatnonzero(y == 1)\n',
    '    require(len(positive) and len(negative), "Both explicitly coded classes are required for AUC.")\n',
    '    draws = np.empty((BOOTSTRAPS, 2))\n',
    '    for replicate in range(BOOTSTRAPS):\n',
    '        sample = np.concatenate([rng.choice(negative, len(negative), replace=True),\n',
    '                                 rng.choice(positive, len(positive), replace=True)])\n',
    '        draws[replicate, 0] = roc_auc_score(y[sample], probability[sample])\n',
    '        draws[replicate, 1] = balanced_accuracy_score(y[sample], probability[sample] >= 0.5)\n',
    '    return np.quantile(draws, [0.025, 0.975], axis=0)\n',
    '\n',
    '\n',
    'def proxy_metric_row(target, scope, fold, y, probability, description, fingerprint,\n',
    '                     threshold, n_train, n_train_positive, unknown_counts):\n',
    '    require(np.isfinite(probability).all(), "Nonfinite out-of-fold proxy probabilities.")\n',
    '    auc = float(roc_auc_score(y, probability))\n',
    '    balanced = float(balanced_accuracy_score(y, probability >= 0.5))\n',
    '    ci = proxy_bootstrap(y, probability, stable_seed("proxy", target, scope, fold))\n',
    '    return {\n',
    '        "target": target, "scope": scope, "fold": fold,\n',
    '        "source_partition": "original_train_60000_plus_validation_15000", "test_used": False,\n',
    '        "feature_count": 87, "n_folds": 5, "n": len(y),\n',
    '        "n_positive": int(y.sum()), "n_negative": int((1 - y).sum()),\n',
    '        "positive_fraction": float(y.mean()), "n_train": n_train,\n',
    '        "n_train_positive": n_train_positive,\n',
    '        "n_train_negative": n_train - n_train_positive if np.isfinite(n_train) else np.nan,\n',
    '        "auc": auc, "auc_ci_low": float(ci[0, 0]), "auc_ci_high": float(ci[1, 0]),\n',
    '        "baseline_auc": 0.5, "auc_minus_baseline": auc - 0.5,\n',
    '        "auc_minus_baseline_ci_low": float(ci[0, 0] - 0.5),\n',
    '        "auc_minus_baseline_ci_high": float(ci[1, 0] - 0.5),\n',
    '        "balanced_accuracy": balanced, "balanced_accuracy_ci_low": float(ci[0, 1]),\n',
    '        "balanced_accuracy_ci_high": float(ci[1, 1]), "baseline_balanced_accuracy": 0.5,\n',
    '        "balanced_accuracy_minus_baseline": balanced - 0.5,\n',
    '        "balanced_accuracy_minus_baseline_ci_low": float(ci[0, 1] - 0.5),\n',
    '        "balanced_accuracy_minus_baseline_ci_high": float(ci[1, 1] - 0.5),\n',
    '        "classification_threshold": 0.5, "fold_training_income_threshold": threshold,\n',
    '        "original_60000_train_income_reference_threshold": description.get("original_60000_train_reference_threshold", np.nan),\n',
    '        "label_definition": description["label_definition"],\n',
    '        "target_coding_json": json.dumps(description["coding"], sort_keys=True),\n',
    '        "verified_observed_values_json": json.dumps(description["observed_values"], sort_keys=True),\n',
    '        "missing_targets_dropped": description["missing_targets_dropped"],\n',
    '        "unseen_fold_validation_categories_json": json.dumps(unknown_counts, sort_keys=True),\n',
    '        "positive_probability_column": "model.classes_ == 1; never flip/maximize AUC after scoring",\n',
    '        "model_parameters_json": json.dumps(PROXY_PARAMS, sort_keys=True),\n',
    '        "bootstrap_replicates": BOOTSTRAPS,\n',
    '        "ci_interpretation": "descriptive stratified held-out-row bootstrap; models and income thresholds fixed, no refit uncertainty",\n',
    '        "protocol": PROTOCOL, "cache_fingerprint": fingerprint,\n',
    '    }\n',
    '\n',
    '\n',
    'def proxy_cv(X, cats, targets, descriptions, fingerprint):\n',
    '    # Imported only in the explicit opt-in path; no training on import or smoke.\n',
    '    from lightgbm import LGBMClassifier\n',
    '\n',
    '    records = []\n',
    '    for target, labels in targets.items():\n',
    '        valid = np.flatnonzero(labels.notna().to_numpy())\n',
    '        observed_labels = labels.iloc[valid].to_numpy()\n',
    '        if target == "income_high":\n',
    '            splitter = KFold(n_splits=5, shuffle=True, random_state=SEED)\n',
    '            folds = splitter.split(valid)\n',
    '        else:\n',
    '            observed_labels = observed_labels.astype(int)\n',
    '            require(min(np.bincount(observed_labels, minlength=2)) >= 5,\n',
    '                    f"{target} has too few members of one class for five-fold stratification.")\n',
    '            splitter = StratifiedKFold(n_splits=5, shuffle=True, random_state=SEED)\n',
    '            folds = splitter.split(valid, observed_labels)\n',
    '        oof_probability = np.full(len(valid), np.nan)\n',
    '        oof_labels = np.full(len(valid), -1, dtype=int)\n',
    '        fold_thresholds = []\n',
    '        for fold, (training, held_out) in enumerate(folds, start=1):\n',
    '            threshold = np.nan\n',
    '            if target == "income_high":\n',
    '                threshold = float(np.median(observed_labels[training]))\n',
    "                # Both labels use only this fold's training threshold. Missing income\n",
    '                # was removed before splitting, and ties belong to the low class.\n',
    '                y_train = (observed_labels[training] > threshold).astype(int)\n',
    '                y_held = (observed_labels[held_out] > threshold).astype(int)\n',
    '                fold_thresholds.append(threshold)\n',
    '            else:\n',
    '                y_train, y_held = observed_labels[training], observed_labels[held_out]\n',
    '            require(set(np.unique(y_train)) == {0, 1} and set(np.unique(y_held)) == {0, 1},\n',
    '                    f"{target} fold {fold} lacks a class; do not change labels or tune around this.")\n',
    '            X_train, X_held, unseen = fold_features(X, cats, valid[training], valid[held_out])\n',
    '            model = LGBMClassifier(**PROXY_PARAMS)\n',
    '            model.fit(X_train, y_train, categorical_feature=cats)\n',
    '            classes = np.asarray(model.classes_)\n',
    '            require(set(classes.tolist()) == {0, 1}, "Unexpected fitted proxy class coding.")\n',
    '            positive_column = int(np.flatnonzero(classes == 1)[0])\n',
    '            probability = model.predict_proba(X_held)[:, positive_column]\n',
    '            oof_probability[held_out], oof_labels[held_out] = probability, y_held\n',
    '            records.append(proxy_metric_row(target, "fold", fold, y_held, probability,\n',
    '                                             descriptions[target], fingerprint, threshold,\n',
    '                                             len(y_train), int(y_train.sum()), unseen))\n',
    '        require(np.isfinite(oof_probability).all() and (oof_labels >= 0).all(),\n',
    '                "Every observed target must have exactly one out-of-fold prediction.")\n',
    '        pooled = proxy_metric_row(target, "pooled_oof", 0, oof_labels, oof_probability,\n',
    '                                  descriptions[target], fingerprint, np.nan, np.nan, np.nan, {})\n',
    '        pooled["fold_income_thresholds_json"] = json.dumps(fold_thresholds)\n',
    '        pooled["pooled_label_caveat"] = (\n',
    '            "fold-local income definitions can vary; pooled OOF AUC is descriptive, read fold results too"\n',
    '            if target == "income_high" else "one explicit binary coding across all folds")\n',
    '        records.append(pooled)\n',
    '    return pd.DataFrame(records)\n',
    '\n',
    '\n',
    'def empty_proxy_table():\n',
    '    return pd.DataFrame(columns=["target", "scope", "fold", "auc", "auc_ci_low", "auc_ci_high",\n',
    '                                 "baseline_auc", "balanced_accuracy", "protocol", "cache_fingerprint"])\n',
    '\n',
    '\n',
    'def load_proxy_cache():\n',
    '    path = WORK / "c_proxy_cv.csv"\n',
    '    if not path.exists():\n',
    '        return empty_proxy_table()\n',
    '    cached = pd.read_csv(path)\n',
    '    if cached.empty:\n',
    '        return cached\n',
    '    required = {"protocol", "cache_fingerprint", "target", "scope", "fold", "test_used",\n',
    '                "feature_count", "source_partition", "verified_observed_values_json",\n',
    '                "target_coding_json", "label_definition", "missing_targets_dropped",\n',
    '                "original_60000_train_income_reference_threshold", "model_parameters_json",\n',
    '                "bootstrap_replicates", "baseline_auc", "baseline_balanced_accuracy"}\n',
    '    require(required.issubset(cached), "Existing c_proxy_cv.csv lacks the verifiable CV cache contract.")\n',
    '    require(cached["protocol"].eq(PROTOCOL).all() and cached["feature_count"].eq(87).all(),\n',
    '            "Existing proxy cache uses a different protocol; it must not be silently refitted.")\n',
    '    require(cached["source_partition"].eq("original_train_60000_plus_validation_15000").all()\n',
    '            and cached["bootstrap_replicates"].eq(BOOTSTRAPS).all()\n',
    '            and cached["baseline_auc"].eq(0.5).all()\n',
    '            and cached["baseline_balanced_accuracy"].eq(0.5).all()\n',
    '            and cached["model_parameters_json"].map(lambda x: json.loads(x) == PROXY_PARAMS).all(),\n',
    '            "Existing proxy cache does not match the frozen non-test training/metric contract.")\n',
    '    require(cached["test_used"].astype(str).str.lower().isin(["false", "0"]).all(),\n',
    '            "Rejecting a proxy cache that used test.")\n',
    '    require(len(cached) == 18 and not cached.duplicated(["target", "scope", "fold"]).any(),\n',
    '            "Expected five fold rows and one pooled row for each of three targets.")\n',
    '    expected = {(target, "fold", fold) for target in ("creditcd", "ownrent", "income_high") for fold in range(1, 6)}\n',
    '    expected |= {(target, "pooled_oof", 0) for target in ("creditcd", "ownrent", "income_high")}\n',
    '    require(set(zip(cached["target"], cached["scope"], cached["fold"])) == expected,\n',
    '            "Proxy cache fold coverage is incomplete.")\n',
    '    require(cached["cache_fingerprint"].nunique() == 1, "Proxy cache contains mixed input fingerprints.")\n',
    '    return cached\n',
    '\n',
    '\n',
    'def ceiling_bridge(explicit_path=None):\n',
    '    candidates = ([inside_work(explicit_path)] if explicit_path else\n',
    '                  [WORK / name for name in ("d_diagnostic_ceiling.csv", "d_sensitive_ceiling.csv",\n',
    '                                             "d_ceiling.csv", "d_diagnostic_ceiling.json")])\n',
    '    available = [path for path in candidates if path.exists()]\n',
    '    if explicit_path:\n',
    '        require(bool(available), f"D\'s diagnostic-ceiling output does not exist: {explicit_path}")\n',
    '    if not available:\n',
    '        return {"status": "pending_D_outputs", "fit_owner": "D", "C_sensitive_fits": 0,\n',
    '                "sensitive_columns": ["asl_flag", "area"],\n',
    '                "boundary": "Separate diagnostic ceiling only; never a deployed-baseline feature or promotion decision.",\n',
    '                "numerical_claims": [], "sources": []}\n',
    '    sources = []\n',
    '    for path in available:\n',
    '        path = inside_work(path)\n',
    '        require(path.suffix.lower() in (".csv", ".json"), "Ceiling bridge accepts only local CSV/JSON tables.")\n',
    '        payload = (pd.read_csv(path).where(lambda x: x.notna(), None).to_dict("records")\n',
    '                   if path.suffix.lower() == ".csv" else json.loads(path.read_text(encoding="utf-8")))\n',
    '        sources.append({"path": str(path), "sha256": sha256_file(path), "raw_D_output": json_safe(payload)})\n',
    '    return {"status": "D_outputs_available_read_only_unverified", "fit_owner": "D", "C_sensitive_fits": 0,\n',
    '            "sensitive_columns": ["asl_flag", "area"], "sources": sources,\n',
    '            "boundary": "Quarantined raw D diagnostic results, separate from deployed baseline and proxy CV.",\n',
    '            "numerical_claims": [],\n',
    '            "review_required": ["Verify paired non-test CV baseline and explicit asl_flag/area ablations.",\n',
    '                                "Verify delta-AUC direction, uncertainty, fold protocol and provenance with D.",\n',
    '                                "Do not use D\'s test numbers for choices or treat ceiling results as deployable."]}\n',
    '\n',
    '\n',
    'def governance_text(summary):\n',
    '    audit = summary.get("audit", {})\n',
    '    bridge = summary["diagnostic_ceiling"]\n',
    '    proxy = summary.get("proxy_cv", {})\n',
    '    source = summary.get("selected_input", {}).get("path", "not available")\n',
    '    return f"""# Workstream C governance: audited, not a certification\n',
    '\n',
    "Partition: {summary['partition']}. Smoke fixture/subsample: {summary.get('smoke', False)}.\n",
    'Selected input: `{source}`. Policy selections are consumed unchanged from A.\n',
    "Proxy status: {proxy.get('status', 'not_run')}. Ceiling status: {bridge['status']}.\n",
    '\n',
    '## Mandatory service-fix floor\n',
    'Any customer with a verified network fault or billing error receives technical or\n',
    'billing remediation regardless of plan price, estimated income, credit, housing,\n',
    'marital status, social-group code, model score or proactive-contact selection.\n',
    'Risk x Value rations only scarce, discretionary proactive outreach. Failure to\n',
    'select an account never removes access to support, complaint handling, defect\n',
    'remediation or consent/opt-out protections. This floor is a mandatory launch\n',
    'requirement, not an implemented service guarantee in this retrospective dataset.\n',
    '\n',
    '## C1: frozen, post-hoc subgroup diagnostics\n',
    'Income, ownrent, marital, creditcd and prizm_social_one are audit-only attributes;\n',
    'none is an input to the deployed baseline. Income is an estimated ordinal 1-9\n',
    'code, not income in currency. Literal unknown category codes remain visible;\n',
    'missing groups and groups absent from the audited partition have explicit rows.\n',
    'Reference categories come from the original 75k train+validation. Newly observed\n',
    'categories are flagged rather than pooled or hidden. Counts are never suppressed.\n',
    '\n',
    'Calibration observed/expected is sum(y)/sum(p_s) in the sample and\n',
    'sum(weight*y)/sum(weight*p_d) in the declared 2% deployment scenario. Ratios\n',
    'near one do not prove calibration in every score band. The model classification\n',
    'threshold is the predeclared sample p_s >= 0.5; its Bayes deployment equivalent is\n',
    "{summary.get('thresholds', {}).get('deployment_equivalent', 'not available')}.\n",
    "Policy capture TPR/FPR, selection, precision and churn-value capture use A's\n",
    'frozen risk and Bayes lists, not a classifier threshold or a test-derived budget.\n',
    'TPR/FPR are conditional-class rates and consequently coincide across these two\n',
    "regimes under A's constant-within-outcome weights; they are not two independent\n",
    "replications. A's deployment weights are scenario population mass, not observed\n",
    'customer counts or demographic prevalence estimates. Deployment interpretation\n',
    'assumes prior/label shift with stable class-conditional feature and group\n',
    'distributions; this assumption is not verified by reweighting the sample.\n',
    '\n',
    'There are {BOOTSTRAPS} paired within-subgroup row bootstrap draws, shared across\n',
    'both policies, the classifier and both prior regimes. Policy differences are\n',
    'Bayes minus risk on each identical draw. Weights, predictions and selections\n',
    'remain fixed. CIs are descriptive percentile intervals, conditional on fitted\n',
    'models, calibration and cutoffs; they exclude refitting/prior uncertainty and\n',
    'have no multiplicity adjustment. Point estimates and CIs are suppressed for\n',
    'n<200; TPR/value-capture/calibration also require >=30 observed positives, FPR\n',
    'requires >=30 negatives, and precision additionally requires adequate selected\n',
    'rows and both selected classes. Undefined denominators and inadequate finite\n',
    'bootstrap coverage are suppressed. Raw counts and scenario masses remain shown.\n',
    'These are audit diagnostics, not Equal Opportunity or other legal compliance\n',
    "certification. Suppressed rows: {audit.get('suppressed_metric_rows', 'not available')}.\n",
    '\n',
    '## C2: recoverability, not deployed sensitive-attribute modeling\n',
    'An explicit --proxy-cv run fits three diagnostic binary models once, using only\n',
    'the original 60k train plus 15k validation. It never uses calibration or test for\n',
    'training or selection. The 87 frozen operational features are the only inputs;\n',
    'category vocabularies are fitted inside each training fold, unknown held-out\n',
    'categories become native missing values, and numeric missingness is handled\n',
    'natively. Missing targets are dropped, not imputed. creditcd maps N=0,Y=1;\n',
    'ownrent maps R=0,O=1. All observed non-test values must be verified against these\n',
    'codings before any fit. Positive probabilities are read from classes_==1;\n',
    'AUC is never flipped after seeing a result, including negative results.\n',
    '\n',
    "Income's original-60k observed median is a fixed non-test reporting reference.\n",
    'Every income CV fold independently fits its own observed training median and\n',
    'codes strictly-above-median as high=1, ties/at-or-below as low=0 on both its train\n',
    'and held-out rows. Fold-local definitions may differ, so pooled income OOF AUC\n',
    'is descriptive and must be read with all five fold results. Median ties are not\n',
    'randomly split to manufacture balanced labels. The reference threshold never\n',
    'uses test and is not substituted for fold-training thresholds.\n',
    '\n',
    'The model is fixed regularized small-capacity LightGBM, six threads, seed\n',
    '20261028, five folds, no hyperparameter search or early-stopping selection.\n',
    'Training class balancing uses training labels only; balanced accuracy uses the\n',
    'fixed 0.5 positive-probability cutoff. Constant-score baseline ROC-AUC and\n',
    'balanced accuracy are 0.5. Paired differences from these constants and 300\n',
    'stratified held-out-row bootstrap CIs are descriptive, not confidence intervals\n',
    'for independent refitted folds. Operational proxy recoverability would support\n',
    'only the caveat that excluding demographic columns reduces direct reliance but\n',
    'does not guarantee statistical independence; no result is asserted before fit.\n',
    'Cached CV results are reused, never retrained by a test audit or smoke run.\n',
    '\n',
    '## C3: exact list-composition shifts\n',
    'c_equity.csv records population, risk, Bayes and Bayes-minus-risk group counts,\n',
    "shares and within-group selections in both the unweighted sample and A's\n",
    'weighted deployment scenario. Denominators are explicit; absent/missing groups\n',
    'stay visible. Income-code and bill distributions include means, inverse-empirical\n',
    'CDF quantiles and observed/missing masses. The raw totmrc_Mean distribution is\n',
    "unimputed and uncapped; A's value distribution is separately labeled as the\n",
    'training-capped/imputed policy value. Weighted masses can be fractional and\n',
    'are not raw counts. These are exact retrospective descriptions, not causal\n',
    'retention, saved revenue, model-quality inference or a parity certification.\n',
    '\n',
    '## C4: diagnostic ceiling boundary\n',
    'asl_flag (Account Spending Limit) and area (geographic market) remain governance-\n',
    "sensitive and prohibited in the deployed baseline and C's proxy features.\n",
    'D owns all sensitive-ceiling fits. C only attaches local, read-only D results\n',
    'with hashes, separately quarantined in c_summary.json; it neither validates nor\n',
    'promotes numerical delta-AUC claims automatically. Pending outputs mean pending,\n',
    'not zero loss. --bridge-only can attach later D tables without rescoring test.\n',
    "Main must verify D's paired non-test CV comparison, sensitivity coding and CIs\n",
    'before citing any ceiling claim. No web citations are fetched or fabricated here.\n',
    '\n',
    '## Partition and claim boundaries\n',
    'All policy/model choices are frozen outside test. v1 previously evaluated the\n',
    'locked 15k test; this historical reuse must remain disclosed. This script guards\n',
    'against repeating a completed or started C test audit and forbids proxy training\n',
    'or smoke on test. Test is reporting only, not a source of thresholds, encoders,\n',
    'feature selection, sensitive ceiling fitting or policy promotion. Risk is not\n',
    'value or responsiveness; retrospective capture is not saved revenue; sample\n',
    'and deployment priors are labeled separately. Pilot treatment/control evidence,\n',
    'service-floor operational enforcement and legal review remain prerequisites to\n',
    'scaling. Root deliverables and v1_frozen are read-only to this workstream.\n',
    '"""\n',
    '\n',
    '\n',
    'def publish_reports(directory, summary, subgroups=None, equity=None, canonical=True):\n',
    '    if subgroups is not None:\n',
    '        subgroups.to_csv(directory / "c_subgroup_robustness.csv", index=False)\n',
    '    if equity is not None:\n',
    '        equity.to_csv(directory / "c_equity.csv", index=False)\n',
    '    write_json(directory / "c_summary.json", summary)\n',
    '    (directory / "c_governance.md").write_text(governance_text(summary), encoding="utf-8")\n',
    '    if canonical:\n',
    '        for name in ("c_subgroup_robustness.csv", "c_equity.csv", "c_summary.json", "c_governance.md"):\n',
    '            require((directory / name).exists(), f"Missing archived report {name}.")\n',
    '            shutil.copyfile(directory / name, WORK / name)\n',
    '\n',
    '\n',
    'def attach_bridge(args):\n',
    '    directory = inside_work(WORK / f"c_{args.partition}")\n',
    '    summary_path = directory / "c_summary.json"\n',
    '    require(summary_path.exists(), "Run the partition audit first; bridge-only cannot score or train.")\n',
    '    summary = json.loads(summary_path.read_text(encoding="utf-8"))\n',
    '    summary["diagnostic_ceiling"] = ceiling_bridge(args.ceiling_results)\n',
    '    latest_path = WORK / "c_summary.json"\n',
    '    latest = json.loads(latest_path.read_text(encoding="utf-8")) if latest_path.exists() else {}\n',
    '    publish_reports(directory, summary, canonical=latest.get("partition") == args.partition)\n',
    '    return summary_path\n',
    '\n',
    '\n',
    'def parser():\n',
    '    result = argparse.ArgumentParser(description=__doc__)\n',
    '    result.add_argument("--partition", choices=("calibration", "test"), default="calibration")\n',
    '    result.add_argument("--proxy-cv", action="store_true",\n',
    '                        help="Opt in once to fixed five-fold proxy fits on the original 75k; reuse an existing matching cache.")\n',
    '    result.add_argument("--smoke", action="store_true",\n',
    '                        help="Calibration-only schema/target/cache validation and 512-row audit; never fits, never publishes canonical outputs.")\n',
    '    result.add_argument("--ceiling-results", type=Path,\n',
    '                        help="Read-only D CSV/JSON inside v2_work; C never fits sensitive ceilings.")\n',
    '    result.add_argument("--bridge-only", action="store_true",\n',
    '                        help="Attach later D outputs to saved reports without reading predictions, rescoring or fitting.")\n',
    '    return result\n',
    '\n',
    '\n',
    'def main(argv=None):\n',
    '    args = parser().parse_args(argv)\n',
    '    require(Path(sys.executable).resolve() == PYTHON.resolve(),\n',
    '            f"Use only the explicit interpreter: {PYTHON}")\n',
    '    require(SEED == 20261028 and THREADS == 6, "Unexpected seed/thread contract in common.py.")\n',
    '    require(WORK.is_dir(), "v2_work must already exist; never create or modify root assets.")\n',
    '    require(not (args.partition == "test" and (args.proxy_cv or args.smoke)),\n',
    '            "Test audits cannot train proxy CV or run smoke. Use calibration for those flags.")\n',
    '    require(not (args.smoke and args.proxy_cv), "Smoke is fit-free; do not combine it with --proxy-cv.")\n',
    '    require(not (args.bridge_only and (args.proxy_cv or args.smoke)),\n',
    '            "Bridge-only cannot train or run smoke.")\n',
    '    if args.bridge_only:\n',
    '        path = attach_bridge(args)\n',
    '        print(f"Updated read-only C4 bridge: {path}")\n',
    '        return\n',
    '    directory = inside_work(WORK / ("c_smoke" if args.smoke else f"c_{args.partition}"))\n',
    '    if args.partition == "test":\n',
    '        require(not (directory / "c_summary.json").exists()\n',
    '                and not (directory / "test_audit_started.json").exists(),\n',
    '                "C test audit is already completed/started. Do not rescore; use --bridge-only for later D outputs.")\n',
    '    data, splits = common.load_data()\n',
    '    universe = reference_groups(data, splits)\n',
    '    frame, selected_path = load_selected(data, splits, args.partition)\n',
    '    bridge = ceiling_bridge(args.ceiling_results)\n',
    '    proxy = load_proxy_cache()\n',
    '    proxy_status = "reused_non_test_cache" if not proxy.empty else "not_run_use_proxy_cv_on_calibration"\n',
    '    descriptions, fingerprint = {}, None\n',
    '    if args.proxy_cv or args.smoke:\n',
    '        X, cats, targets, descriptions, fingerprint = proxy_inputs(data, splits)\n',
    '        if not proxy.empty:\n',
    '            require(proxy["cache_fingerprint"].eq(fingerprint).all(),\n',
    '                    "Proxy inputs/spec differ from the once-run cache. Do not silently refit or chase results.")\n',
    '        if args.proxy_cv and proxy.empty:\n',
    '            marker = WORK / "c_proxy_cv_started.json"\n',
    '            require(not marker.exists(),\n',
    '                    "Proxy CV was already started without a complete cache. Do not automatically repeat fits; investigate the prior run.")\n',
    '            with marker.open("x", encoding="utf-8") as handle:\n',
    '                json.dump({"protocol": PROTOCOL, "cache_fingerprint": fingerprint,\n',
    '                           "parameters": PROXY_PARAMS, "planned_fits": 15,\n',
    '                           "source_partition": "original_train_60000_plus_validation_15000",\n',
    '                           "test_used": False}, handle, indent=2)\n',
    '            proxy = proxy_cv(X, cats, targets, descriptions, fingerprint)\n',
    '            proxy.to_csv(WORK / "c_proxy_cv.csv", index=False)\n',
    '            proxy_status = "completed_once_original_75k"\n',
    '        elif args.smoke and proxy.empty:\n',
    '            proxy_status = "smoke_verified_codings_no_fits"\n',
    '    if not descriptions and not proxy.empty:\n',
    '        for row in proxy.loc[proxy["scope"].eq("pooled_oof")].to_dict("records"):\n',
    '            descriptions[row["target"]] = {\n',
