# %% V2 module workstream_d
_v2_materialize('workstream_d', ''.join([
    '"""Local-only D1-D5/C4 experiments; importing this module never fits a model.\n',
    '\n',
    'Run with the shared Python 3.11 interpreter and --run, or --smoke for a separate\n',
    'non-decision, reduced-compute end-to-end check. No calibration-policy/test rows\n',
    'are passed to any experiment. The only 75k fit is a BASELINE RESUBSTITUTION\n',
    'learning-curve diagnostic, not a production refit or a held-out 75k result.\n',
    '\n',
    'Outer CV: sequential 2 x 5 stratified folds. All adaptive feature selection and\n',
    "blend weights are learned inside an outer fold's development portion. Its\n",
    'separate 20% calibration slice supplies sigmoid calibration and contact cutoffs.\n',
    'Models are then refitted on the complete outer training fold, never outer labels.\n',
    'This is split-calibrate/refit calibration (48k -> 60k fit-size shift), not a claim\n',
    'that the calibration model and the final model are the very same fitted object.\n',
    '\n',
    'Intervals use conservative Nadeau-Bengio-style corrected t standard errors:\n',
    ' sqrt((1 / number_of_paired_folds + mean(test_n / train_n)) * sample_variance).\n',
    'Degrees of freedom are k-1=4, conservatively not 9 independent repeated folds.\n',
    'Gate D additionally requires non-positive corrected upper bounds for weighted\n',
    "Brier AND log loss on the SAME baseline-defined tail, and on each policy's tail.\n",
    'All thresholds defining these nominal weighted top deciles come from inner\n',
    'held-out calibration rows, not from sorting the outer holdout to set a cutoff.\n',
    '"""\n',
    'from __future__ import annotations\n',
    '\n',
    'import os\n',
    '\n',
    'for _variable in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS",\n',
    '                  "NUMEXPR_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):\n',
    '    os.environ[_variable] = "6"\n',
    '\n',
    'import argparse\n',
    'from dataclasses import asdict, dataclass\n',
    'import hashlib\n',
    'import importlib.metadata\n',
    'import json\n',
    'from pathlib import Path\n',
    'import sys\n',
    'import time\n',
    'import warnings\n',
    '\n',
    'import numpy as np\n',
    'import pandas as pd\n',
    'from scipy import sparse\n',
    'from scipy.optimize import minimize\n',
    'from scipy.special import expit, logit\n',
    'from scipy.stats import t as student_t\n',
    'from sklearn.base import BaseEstimator, TransformerMixin\n',
    'from sklearn.compose import ColumnTransformer\n',
    'from sklearn.exceptions import ConvergenceWarning\n',
    'from sklearn.impute import SimpleImputer\n',
    'from sklearn.linear_model import LogisticRegression\n',
    'from sklearn.metrics import roc_auc_score\n',
    'from sklearn.model_selection import StratifiedKFold, train_test_split\n',
    'from sklearn.pipeline import Pipeline\n',
    'from sklearn.preprocessing import OneHotEncoder, SplineTransformer, StandardScaler\n',
    'from threadpoolctl import threadpool_limits\n',
    '\n',
    'try:\n',
    '    from . import common\n',
    'except ImportError:\n',
    '    import common\n',
    '\n',
    'SEED = common.SEED\n',
    'THREADS = common.THREADS\n',
    'SHARED_PYTHON = Path("C:/Users/FGstore/AppData/Local/Programs/Python/Python311/python.exe")\n',
    'REPEATS, FOLDS, INNER_FOLDS = 2, 5, 3\n',
    'DEPLOYMENT_PRIOR, CONTACT_SHARE, M_ESTIMATE = .02, .10, 50.0\n',
    'SMOKE_ROWS = 1000\n',
    'GROUPS = ("g1_temporal", "g2_range", "g3_billing_gaps", "g4_call_care",\n',
    '          "g5_equipment_cycle", "g6_tenure_pricing")\n',
    'AVAILABLE_GROUPS = tuple(g for g in GROUPS if g != "g2_range")\n',
    'BLEND_MODELS = ("lgbm", "catboost", "xgboost", "spline_logistic")\n',
    'BASELINE_NAME = "baseline_lgbm"\n',
    '\n',
    '# No early stopping, grid search, or outer-label-dependent iteration budgets.\n',
    'MODEL_SPECS = {\n',
    '    "lgbm": dict(n_estimators=385, learning_rate=.03, num_leaves=31,\n',
    '                 min_child_samples=100, reg_lambda=12, subsample=.85,\n',
    '                 subsample_freq=1, colsample_bytree=.85, n_jobs=THREADS,\n',
    '                 random_state=SEED, verbosity=-1, deterministic=True,\n',
    '                 force_col_wise=True),\n',
    '    "catboost": dict(iterations=500, learning_rate=.04, depth=6,\n',
    '                     l2_leaf_reg=8, loss_function="Logloss", random_seed=SEED,\n',
    '                     thread_count=THREADS, task_type="CPU",\n',
    '                     allow_writing_files=False, verbose=False),\n',
    '    "xgboost": dict(n_estimators=500, learning_rate=.04, max_depth=5,\n',
    '                    min_child_weight=20, reg_lambda=12, subsample=.85,\n',
    '                    colsample_bytree=.85, tree_method="hist",\n',
    '                    enable_categorical=True, eval_metric="logloss",\n',
    '                    n_jobs=THREADS, random_state=SEED),\n',
    '    "spline_logistic": dict(C=.1, solver="lbfgs", max_iter=1500,\n',
    '                            random_state=SEED),\n',
    '}\n',
    '\n',
    'GROUP_NOTES = {\n',
    '    "g1_temporal": {\n',
    '        "status": "available",\n',
    '        "definition": "avg3/avg6/lifetime ratios and differences for mou/qty/rev; "\n',
    '                      "mou_Mean and rev_Mean versus avg3 are explicitly undated comparisons",\n',
    '        "window_caveat": "avg3=3 months; avg6=6 months; _Mean window unspecified. "\n',
    '                         "No inferred 3/4-month _Mean, time-normalized acceleration, "\n',
    '                         "or reinterpretation of change_* percentages as absolute changes.",\n',
    '    },\n',
    '    "g2_range": {"status": "unavailable", "reason": "Neither supplied CSV contains "\n',
    '                 "_Range columns; totmrc_Range, ovrrev_Range, mou_Range cannot be tested. "\n',
    '                 "No invented fields or reconstructed volatility."},\n',
    '    "g3_billing_gaps": {"status": "available", "definition":\n',
    '                        "totrev-adjrev; totmou-adjmou; totcalls-adjqty"},\n',
    '    "g4_call_care": {"status": "available", "definition":\n',
    '                     "comp_vce_Mean/(plcd_vce_Mean+.5); "\n',
    '                     "inonemin_Mean/(complete_Mean+.5); "\n',
    '                     "ccrndmou_Mean/(custcare_Mean+.1)"},\n',
    '    "g5_equipment_cycle": {"status": "available", "definition":\n',
    '                           "retain v1\'s valid eqpdays/(30.4375*max(months,1)), without duplicating it; "\n',
    '                           "add valid eqpdays/max(phones,1), months%12, and "\n',
    '                           "hnd_price exact observed price tiers, m=50 encoding. "\n',
    '                           "Every training value is inner-OOF; inference maps fit training only."},\n',
    '    "g6_tenure_pricing": {"status": "available", "definition":\n',
    '                          "nonnegative totmrc_Mean/max(tenure-decile train median,1); "\n',
    '                          "tenure quantile edges, missing-tenure fill and price medians "\n',
    '                          "fit exclusively on the current fitting rows"},\n',
    '}\n',
    '\n',
    '\n',
    '@dataclass(frozen=True)\n',
    'class Recipe:\n',
    '    backend: str = "lgbm"\n',
    '    groups: tuple[str, ...] = ()\n',
    '    drop: tuple[str, ...] = ()\n',
    '    sensitive: bool = False\n',
    '    value_weighted: bool = False\n',
    '\n',
    '\n',
    '@dataclass\n',
    'class Fold:\n',
    '    repeat: int\n',
    '    number: int\n',
    '    train: np.ndarray\n',
    '    test: np.ndarray\n',
    '    development: np.ndarray\n',
    '    calibration: np.ndarray\n',
    '\n',
    '    @property\n',
    '    def tag(self):\n',
    '        return f"r{self.repeat}_f{self.number}"\n',
    '\n',
    '\n',
    'def _clean(value):\n',
    '    if isinstance(value, dict):\n',
    '        return {str(k): _clean(v) for k, v in value.items()}\n',
    '    if isinstance(value, (list, tuple)):\n',
    '        return [_clean(v) for v in value]\n',
    '    if isinstance(value, np.ndarray):\n',
    '        return _clean(value.tolist())\n',
    '    if isinstance(value, np.generic):\n',
    '        return _clean(value.item())\n',
    '    if isinstance(value, float) and not np.isfinite(value):\n',
    '        return None\n',
    '    return value\n',
    '\n',
    '\n',
    'def _digest(value):\n',
    '    return hashlib.sha256(json.dumps(_clean(value), sort_keys=True).encode()).hexdigest()\n',
    '\n',
    '\n',
    'def _indices_hash(indices):\n',
    '    return hashlib.sha256(np.asarray(indices, dtype="<i8").tobytes()).hexdigest()\n',
    '\n',
    '\n',
    'def _file_hash(path):\n',
    '    result = hashlib.sha256()\n',
    '    with Path(path).open("rb") as source:\n',
    '        for block in iter(lambda: source.read(1024 * 1024), b""):\n',
    '            result.update(block)\n',
    '    return result.hexdigest()\n',
    '\n',
    '\n',
    'class Artifacts:\n',
    '    """Atomic completion markers; rerunning the identical command resumes fits."""\n',
    '\n',
    '    def __init__(self, directory):\n',
    '        self.directory = Path(directory).resolve()\n',
    '        work = common.WORK.resolve()\n',
    '        if self.directory == work or work not in self.directory.parents:\n',
    '            raise ValueError("Artifacts must be in a dedicated child of v2_work")\n',
    '        self.directory.mkdir(parents=True, exist_ok=True)\n',
    '        for name in ("cache", "folds", "oof"):\n',
    '            (self.directory / name).mkdir(exist_ok=True)\n',
    '\n',
    '    def path(self, relative):\n',
    '        target = (self.directory / relative).resolve()\n',
    '        if self.directory not in target.parents:\n',
    '            raise ValueError("Artifact path escapes the experiment directory")\n',
    '        return target\n',
    '\n',
    '    def replace(self, temporary, target):\n',
    '        # Windows readers can briefly lock an otherwise writable destination.\n',
    '        for attempt in range(8):\n',
    '            try:\n',
    '                os.replace(temporary, target)\n',
    '                return\n',
    '            except PermissionError as error:\n',
    "                if os.name != 'nt' or getattr(error, 'winerror', None) not in (5, 32, 33) or attempt == 7:\n",
    '                    raise\n',
    '                time.sleep(.02 * 2 ** attempt)\n',
    '\n',
    '    def json(self, relative, value):\n',
    '        target = self.path(relative)\n',
    '        temporary = target.with_name(target.name + ".tmp")\n',
    '        temporary.write_text(json.dumps(_clean(value), indent=2, allow_nan=False),\n',
    '                             encoding="utf-8")\n',
    '        self.replace(temporary, target)\n',
    '\n',
    '    def read_json(self, relative):\n',
    '        return json.loads(self.path(relative).read_text(encoding="utf-8"))\n',
    '\n',
    '    def npz(self, relative, **arrays):\n',
    '        target = self.path(relative)\n',
    '        temporary = target.with_name(target.name + ".tmp")\n',
    '        with temporary.open("wb") as handle:\n',
    '            np.savez_compressed(handle, **arrays)\n',
    '        self.replace(temporary, target)\n',
    '\n',
    '    def table(self, relative, records):\n',
    '        frame = records if isinstance(records, pd.DataFrame) else pd.DataFrame(records)\n',
    '        target = self.path(relative + ".csv")\n',
    '        temporary = target.with_name(target.name + ".tmp")\n',
    '        frame.to_csv(temporary, index=False, float_format="%.12g")\n',
    '        self.replace(temporary, target)\n',
    '        self.json(relative + ".json", frame.to_dict(orient="records"))\n',
    '\n',
    '    def bind(self, metadata):\n',
    '        path = self.path("run_spec.json")\n',
    '        if path.exists():\n',
    '            previous = self.read_json("run_spec.json")\n',
    '            if previous != _clean(metadata):\n',
    '                raise RuntimeError("Resume specification/data/code mismatch. Use a new "\n',
    '                                   "v2_work output directory; existing results were not changed.")\n',
    '        else:\n',
    '            self.json("run_spec.json", metadata)\n',
    '\n',
    '\n',
    'def non_test_pool(data, splits):\n',
    '    """Discard forbidden partitions before any feature or model function is called."""\n',
    '    if len(splits["train"]) != 60000 or len(splits["validation"]) != 15000:\n',
    '        raise AssertionError("Original 60k/15k training partitions required")\n',
    '    keep = np.r_[splits["train"], splits["validation"]].astype(int)\n',
    '    forbidden = np.r_[splits["calibration_policy"], splits["test"]]\n',
    '    if len(np.unique(keep)) != 75000 or np.intersect1d(keep, forbidden).size:\n',
    '        raise AssertionError("Non-test pool is not exactly original train+validation")\n',
    '    pool = data.iloc[keep].copy().reset_index(drop=True)\n',
    '    if not pool.Customer_ID.is_unique or not set(pool.churn.unique()) <= {0, 1}:\n',
    '        raise AssertionError("Unique customers and binary targets required")\n',
    '    pool["_original_partition"] = np.r_[np.repeat("train", 60000),\n',
    '                                        np.repeat("validation", 15000)]\n',
    '    return pool\n',
    '\n',
    '\n',
    'def outer_folds(y):\n',
    '    y = np.asarray(y)\n',
    '    for repeat in range(REPEATS):\n',
    '        splitter = StratifiedKFold(FOLDS, shuffle=True, random_state=SEED + repeat)\n',
    '        for number, (train, test) in enumerate(splitter.split(np.zeros(len(y)), y)):\n',
    '            development, calibration = train_test_split(\n',
    '                train, test_size=.20, stratify=y[train],\n',
    '                random_state=SEED + 1000 + repeat * FOLDS + number)\n',
    '            yield Fold(repeat, number, np.sort(train), np.sort(test),\n',
    '                       np.sort(development), np.sort(calibration))\n',
    '\n',
    '\n',
    'def corrected_interval(differences, ratios, folds=FOLDS):\n',
    '    """Paired intervals, never an IID bootstrap over repeated folds."""\n',
    '    difference = np.asarray(differences, dtype=float)\n',
    '    ratio = np.broadcast_to(np.asarray(ratios, dtype=float), difference.shape)\n',
    '    valid = np.isfinite(difference) & np.isfinite(ratio)\n',
    '    if not valid.all() or len(difference) < 2:\n',
    '        return dict(n_pairs=len(difference), mean=None, lower=None, upper=None,\n',
    '                    corrected_se=None, test_train_ratio=None, df=folds - 1,\n',
    '                    complete=False)\n',
    '    variance = float(np.var(difference, ddof=1))\n',
    '    correction = 1 / len(difference) + float(np.mean(ratio))\n',
    '    standard_error = float(np.sqrt(correction * variance))\n',
    '    degrees = min(folds - 1, len(difference) - 1)\n',
    '    margin = float(student_t.ppf(.975, degrees) * standard_error)\n',
    '    mean = float(difference.mean())\n',
    '    return dict(n_pairs=len(difference), mean=mean, lower=mean - margin,\n',
    '                upper=mean + margin, corrected_se=standard_error,\n',
    '                test_train_ratio=float(ratio.mean()), df=degrees, complete=True)\n',
    '\n',
    '\n',
    'def _price_keys(series):\n',
    '    # Price is already a discrete observed field, not a learned/external tier scheme.\n',
    '    return pd.to_numeric(series, errors="coerce").map(\n',
    '        lambda value: "__MISSING__" if pd.isna(value) else format(float(value), ".12g"))\n',
    '\n',
    '\n',
    'def m_estimate_map(keys, y, m=M_ESTIMATE):\n',
    '    y = np.asarray(y, dtype=float)\n',
    '    prior = float(y.mean())\n',
    '    aggregate = pd.DataFrame({"key": np.asarray(keys), "y": y}).groupby("key").y.agg(\n',
    '        ["sum", "count"])\n',
    '    return ((aggregate["sum"] + m * prior) / (aggregate["count"] + m)).to_dict(), prior\n',
    '\n',
    '\n',
    'def oof_m_estimate(keys, y, seed=SEED, folds=INNER_FOLDS):\n',
    '    keys, y = pd.Series(keys).reset_index(drop=True), np.asarray(y)\n',
    '    output = np.full(len(y), np.nan)\n',
    '    splitter = StratifiedKFold(folds, shuffle=True, random_state=seed)\n',
    '    for train, heldout in splitter.split(np.zeros(len(y)), y):\n',
    '        mapping, prior = m_estimate_map(keys.iloc[train], y[train])\n',
    '        output[heldout] = keys.iloc[heldout].map(mapping).fillna(prior)\n',
    '    assert np.isfinite(output).all()\n',
    '    return output\n',
    '\n',
    '\n',
    'def tenure_pricing(data, train):\n',
    '    tenure = pd.to_numeric(data.months, errors="coerce")\n',
    '    fit_tenure = tenure.iloc[train].dropna()\n',
    '    fill = float(fit_tenure.median()) if len(fit_tenure) else 0.0\n',
    '    edges = (np.unique(np.quantile(fit_tenure, np.arange(.1, 1, .1)))\n',
    '             if len(fit_tenure) else np.array([], dtype=float))\n',
    '    bins = np.searchsorted(edges, tenure.fillna(fill).to_numpy(), side="right")\n',
    '    price = pd.to_numeric(data.totmrc_Mean, errors="coerce").clip(lower=0)\n',
    '    fit_price = price.iloc[train]\n',
    '    fallback = float(fit_price.median()) if fit_price.notna().any() else 0.0\n',
    '    medians = pd.DataFrame({"bin": bins[train], "price": fit_price.to_numpy()}).groupby(\n',
    '        "bin").price.median().dropna().to_dict()\n',
    '    denominator = pd.Series(bins).map(medians).fillna(fallback).clip(lower=1)\n',
    '    feature = price.to_numpy() / denominator.to_numpy()\n',
    '    return feature, dict(tenure_edges=edges, tenure_fill=fill,\n',
    '                         price_medians=medians, fallback_price_median=fallback)\n',
    '\n',
    '\n',
    'def design(data, train, predict, recipe):\n',
    '    """Build fit-local features, including cross-fitted target encoding."""\n',
    '    if "_original_partition" in data:\n',
    '        source = data.drop(columns="_original_partition")\n',
    '    else:\n',
    '        source = data\n',
    '    X, cats = common.operational_features(source, np.asarray(train))\n',
    '    if len(X.columns) != 87:\n',
    '        raise AssertionError("Frozen operational_features must reproduce exactly 87 columns")\n',
    '    base = X.columns.tolist()\n',
    '    metadata = {"base_features": base, "category_vocabularies":\n',
    '                {c: X[c].cat.categories.tolist() for c in cats}, "feature_statistics": {}}\n',
    '    for group in recipe.groups:\n',
    '        if group not in AVAILABLE_GROUPS:\n',
    '            raise ValueError(f"Unavailable or unknown feature group: {group}")\n',
    '        if group == "g1_temporal":\n',
    '            for kind in ("mou", "qty", "rev"):\n',
    '                recent, six, lifetime = (source[f"avg3{kind}"], source[f"avg6{kind}"],\n',
    '                                         source[f"avg{kind}"])\n',
    '                X[f"g1_{kind}_3_minus_6"] = recent - six\n',
    '                X[f"g1_{kind}_3_minus_lifetime"] = recent - lifetime\n',
    '                # Revenue/usage ratios are already in v1; avoid duplicate additions.\n',
    '                if kind == "qty":\n',
    '                    X["g1_qty_3_to_6"] = recent / six.clip(lower=1)\n',
    '                    X["g1_qty_3_to_lifetime"] = recent / lifetime.clip(lower=1)\n',
    '                if kind in ("mou", "rev"):\n',
    '                    X[f"g1_{kind}_unspecified_mean_minus_3"] = source[f"{kind}_Mean"] - recent\n',
    '                    X[f"g1_{kind}_unspecified_mean_to_3"] = source[f"{kind}_Mean"] / recent.clip(lower=1)\n',
    '        elif group == "g3_billing_gaps":\n',
    '            for left, right in (("totrev", "adjrev"), ("totmou", "adjmou"), ("totcalls", "adjqty")):\n',
    '                X[f"g3_{left}_minus_{right}"] = source[left] - source[right]\n',
    '        elif group == "g4_call_care":\n',
    '            X["g4_completion_ratio"] = source.comp_vce_Mean / (source.plcd_vce_Mean + .5)\n',
    '            X["g4_short_inbound_ratio"] = source.inonemin_Mean / (source.complete_Mean + .5)\n',
    '            X["g4_care_minutes_per_call"] = source.ccrndmou_Mean / (source.custcare_Mean + .1)\n',
    '        elif group == "g5_equipment_cycle":\n',
    '            days = source.eqpdays.where(source.eqpdays >= 0)\n',
    "            # The months-relative equipment ratio already exists among v1's 87.\n",
    '            X["g5_equipment_days_per_phone"] = days / source.phones.clip(lower=1)\n',
    '            X["g5_months_mod_12"] = source.months % 12\n',
    '            keys = _price_keys(source.hnd_price)\n',
    '            mapping, prior = m_estimate_map(keys.iloc[train], source.churn.iloc[train])\n',
    '            X["g5_hnd_price_oof_m50"] = keys.map(mapping).fillna(prior).to_numpy()\n',
    '            X.iloc[train, X.columns.get_loc("g5_hnd_price_oof_m50")] = oof_m_estimate(\n',
    '                keys.iloc[train], source.churn.iloc[train].to_numpy())\n',
    '            metadata["feature_statistics"]["hnd_price_encoding"] = {\n',
    '                "m": M_ESTIMATE, "mapping": mapping, "prior": prior,\n',
    '                "training_values": "3-fold inner-OOF, including when fit is itself an inner fold"}\n',
    '        elif group == "g6_tenure_pricing":\n',
    '            feature, statistics = tenure_pricing(source, train)\n',
    '            X["g6_tenure_relative_recurring_price"] = feature\n',
    '            metadata["feature_statistics"]["tenure_pricing"] = statistics\n',
    '    if recipe.sensitive:\n',
    '        for column in ("asl_flag", "area"):\n',
    '            values = source[column].fillna("__MISSING__").astype(str)\n',
    '            vocabulary = sorted(values.iloc[train].unique())\n',
    '            X[column] = pd.Categorical(values, categories=vocabulary)\n',
    '            cats.append(column)\n',
    '            metadata["category_vocabularies"][column] = vocabulary\n',
    '    X = X.drop(columns=list(recipe.drop))\n',
    '    cats = [c for c in cats if c in X]\n',
    '    numeric = [c for c in X if c not in cats]\n',
    '    X[numeric] = X[numeric].replace([np.inf, -np.inf], np.nan).astype("float32")\n',
    '    if not recipe.sensitive and {"asl_flag", "area"}.intersection(X):\n',
    '        raise AssertionError("Sensitive attributes leaked into deployable features")\n',
    '    metadata["features"] = X.columns.tolist()\n',
    '    metadata["categorical_features"] = cats\n',
    '    return X.iloc[train].copy(), X.iloc[predict].copy(), cats, metadata\n',
    '\n',
    '\n',
    'def model_spec(backend, smoke=False):\n',
    '    specification = MODEL_SPECS[backend].copy()\n',
    '    if smoke:\n',
    '        if backend == "lgbm":\n',
    '            specification.update(n_estimators=8, num_leaves=7, min_child_samples=5)\n',
    '        elif backend == "catboost":\n',
    '            specification.update(iterations=8, depth=3)\n',
    '        elif backend == "xgboost":\n',
    '            specification.update(n_estimators=8, max_depth=3, min_child_weight=2)\n',
    '        else:\n',
    '            specification["max_iter"] = 200\n',
    '    return specification\n',
    '\n',
    '\n',
    'class TrainQuantileSplines(TransformerMixin, BaseEstimator):\n',
    '    """SplineTransformer with train quantile knots, robust to ties/constants.\n',
    '\n',
    '    Sparse/binary billing and missingness fields have tied quantiles. Using an\n',
    '    unmodified five-knot quantile spline can yield degenerate BSplines. We retain\n',
    '    unique TRAIN quantiles per feature; constant columns stay at the fitted value.\n',
    '    This is a fixed preprocessing rule, not an outer-data-driven model choice.\n',
    '    """\n',
    '\n',
    '    def __init__(self, n_knots=5, degree=3):\n',
    '        self.n_knots, self.degree = n_knots, degree\n',
    '\n',
    '    def fit(self, X, y=None):\n',
    '        X = np.asarray(X, dtype=float)\n',
    '        self.n_features_in_ = X.shape[1]\n',
    '        self.transformers_, self.quantile_knots_ = [], []\n',
    '        for column in range(self.n_features_in_):\n',
    '            knots = np.unique(np.quantile(X[:, column], np.linspace(0, 1, self.n_knots)))\n',
    '            self.quantile_knots_.append(knots)\n',
    '            transformer = None\n',
    '            if len(knots) > 1:\n',
    '                transformer = SplineTransformer(knots=knots.reshape(-1, 1), degree=self.degree,\n',
    '                                                include_bias=False, extrapolation="constant",\n',
    '                                                sparse_output=True).fit(X[:, [column]])\n',
    '            self.transformers_.append(transformer)\n',
    '        return self\n',
    '\n',
    '    def transform(self, X):\n',
    '        X = np.asarray(X, dtype=float)\n',
    '        if X.shape[1] != self.n_features_in_:\n',
    '            raise ValueError("Spline input feature count changed")\n',
    '        blocks = [transformer.transform(X[:, [column]]) if transformer is not None\n',
    '                  else sparse.csr_matrix(np.full((len(X), 1), self.quantile_knots_[column][0]))\n',
    '                  for column, transformer in enumerate(self.transformers_)]\n',
    '        return sparse.hstack(blocks, format="csr")\n',
    '\n',
    '\n',
    'def spline_pipeline(X, cats, specification, smoke=False):\n',
    '    numeric = [c for c in X if c not in cats]\n',
    '    numeric_pipeline = Pipeline([\n',
    '        ("imputer", SimpleImputer(strategy="median", add_indicator=True,\n',
    '                                 keep_empty_features=True)),\n',
    '        ("spline", TrainQuantileSplines(n_knots=3 if smoke else 5, degree=3)),\n',
    '        ("scale", StandardScaler(with_mean=False)),\n',
    '    ])\n',
    '    preprocessing = ColumnTransformer([\n',
    '        ("numeric", numeric_pipeline, numeric),\n',
    '        ("category", OneHotEncoder(handle_unknown="ignore", min_frequency=25,\n',
    '                                   sparse_output=True), cats),\n',
    '    ], sparse_threshold=1.0)\n',
    '    return Pipeline([("preprocessing", preprocessing),\n',
    '                     ("model", LogisticRegression(**specification))])\n',
    '\n',
    '\n',
    'def fit_blend(oof_probabilities, y):\n',
    '    probabilities, y = np.asarray(oof_probabilities), np.asarray(y)\n',
    '    logits = logit(np.clip(probabilities, 1e-6, 1 - 1e-6))\n',
    '    n_models = logits.shape[1]\n',
    '\n',
    '    def objective(weights):\n',
    '        score = logits @ weights\n',
    '        loss = float(np.mean(np.logaddexp(0, score) - y * score))\n',
    '        gradient = logits.T @ (expit(score) - y) / len(y)\n',
    '        return loss, gradient\n',
    '\n',
    '    result = minimize(objective, np.full(n_models, 1 / n_models), jac=True,\n',
    '                      method="SLSQP", bounds=[(0, 1)] * n_models,\n',
    '                      constraints=[{"type": "eq", "fun": lambda w: w.sum() - 1,\n',
    '                                    "jac": lambda w: np.ones_like(w)}],\n',
    '                      options={"maxiter": 200, "ftol": 1e-10})\n',
    '    if not result.success or abs(result.x.sum() - 1) > 1e-6 or result.x.min() < -1e-8:\n',
    '        raise RuntimeError(f"Constrained OOF blending failed: {result.message}")\n',
    '    weights = np.clip(result.x, 0, 1)\n',
    '    return weights / weights.sum(), {"optimizer": "SLSQP", "objective": "OOF log loss",\n',
    '                                    "iterations": int(result.nit), "success": True}\n',
    '\n',
    '\n',
    'def blend_predict(probabilities, weights):\n',
    '    return expit(logit(np.clip(probabilities, 1e-6, 1 - 1e-6)) @ weights)\n',
    '\n',
    '\n',
    'def weighted_losses(y, probability, weight, mask):\n',
    '    y, probability, weight, mask = map(np.asarray, (y, probability, weight, mask))\n',
    '    if not mask.any() or weight[mask].sum() <= 0:\n',
    '        return np.nan, np.nan\n',
    '    p, target, w = np.clip(probability[mask], 1e-6, 1 - 1e-6), y[mask], weight[mask]\n',
    '    brier = float(np.average((target - p) ** 2, weights=w))\n',
    '    loss = float(np.average(-(target * np.log(p) + (1 - target) * np.log1p(-p)), weights=w))\n',
    '    return brier, loss\n',
    '\n',
    '\n',
    'def calibrated_predictions(raw_calibration, y_calibration, raw_outer,\n',
    '                           value_calibration, value_outer):\n',
    '    with warnings.catch_warnings(record=True) as recorded:\n',
    '        warnings.simplefilter("always", ConvergenceWarning)\n',
    '        calibrator = common.Calibrator("sigmoid").fit(raw_calibration, y_calibration)\n',
    '    calibration_converged = not any(issubclass(w.category, ConvergenceWarning) for w in recorded)\n',
    '    calibration_probability = calibrator.predict(raw_calibration)\n',
    '    outer_probability = calibrator.predict(raw_outer)\n',
    '    sample_prior = float(np.mean(y_calibration))\n',
    '    pd_calibration = common.shift(calibration_probability, DEPLOYMENT_PRIOR, sample_prior)\n',
    '    pd_outer = common.shift(outer_probability, DEPLOYMENT_PRIOR, sample_prior)\n',
    '    calibration_weights = common.weights(y_calibration, DEPLOYMENT_PRIOR,\n',
    '                                         population=len(y_calibration))\n',
    '    cutoff = common.cutoff(pd_calibration * value_calibration,\n',
    '                           calibration_weights, CONTACT_SHARE)\n',
    '    sample_cutoff = common.cutoff(calibration_probability, np.ones(len(y_calibration)), .1)\n',
    '    return dict(p_s=outer_probability, p_d=pd_outer,\n',
    '                score=pd_outer * value_outer, threshold=cutoff,\n',
    '                sample_risk_threshold=sample_cutoff, sample_prior=sample_prior,\n',
    '                calibration_slope=float(calibrator.model.coef_[0, 0]),\n',
    '                calibration_intercept=float(calibrator.model.intercept_[0]),\n',
    '                calibration_converged=calibration_converged,\n',
    '                calibration_method="fixed sigmoid; inner held-out calibration slice")\n',
    '\n',
    '\n',
    'def measure(fold, y, raw, prediction, value, baseline_tail=None):\n',
    '    weight = common.weights(y, DEPLOYMENT_PRIOR, population=len(y))\n',
    '    own = prediction["score"] >= prediction["threshold"]\n',
    '    shared = own if baseline_tail is None else np.asarray(baseline_tail)\n',
    '    own_brier, own_loss = weighted_losses(y, prediction["p_d"], weight, own)\n',
    '    shared_brier, shared_loss = weighted_losses(y, prediction["p_d"], weight, shared)\n',
    '    sample_tail = prediction["p_s"] >= prediction["sample_risk_threshold"]\n',
    '    sample_brier, sample_loss = weighted_losses(y, prediction["p_s"], np.ones(len(y)), sample_tail)\n',
    '    brier, loss = weighted_losses(y, prediction["p_s"], np.ones(len(y)), np.ones(len(y), bool))\n',
    '    weighted_brier, weighted_loss = weighted_losses(y, prediction["p_d"], weight, np.ones(len(y), bool))\n',
    '    churn_value = weight * np.asarray(y) * value\n',
    '    denominator = churn_value.sum()\n',
    '    metrics = dict(repeat=fold.repeat, fold=fold.number, train_n=len(fold.train),\n',
    '                   heldout_n=len(fold.test), development_n=len(fold.development),\n',
    '                   calibration_n=len(fold.calibration), auc=float(roc_auc_score(y, raw)),\n',
    '                   calibrated_auc=float(roc_auc_score(y, prediction["p_s"])),\n',
    '                   sample_brier=brier, sample_logloss=loss,\n',
    '                   deployment_weighted_brier=weighted_brier,\n',
    '                   deployment_weighted_logloss=weighted_loss,\n',
    '                   baseline_tail_brier=shared_brier, baseline_tail_logloss=shared_loss,\n',
    '                   own_tail_brier=own_brier, own_tail_logloss=own_loss,\n',
    '                   sample_risk_tail_brier=sample_brier, sample_risk_tail_logloss=sample_loss,\n',
    '                   weighted_value_capture=float(churn_value[own].sum() / denominator)\n',
    '                   if denominator > 0 else np.nan,\n',
    '                   weighted_contact_share=float(weight[own].sum() / weight.sum()),\n',
    '                   raw_contacts=int(own.sum()), baseline_tail_n=int(shared.sum()),\n',
    '                   threshold=prediction["threshold"], sample_prior=prediction["sample_prior"],\n',
    '                   calibration_slope=prediction["calibration_slope"],\n',
    '                   calibration_intercept=prediction["calibration_intercept"])\n',
    '    return metrics, own, shared\n',
    '\n',
    '\n',
    'def feature_families(features):\n',
    '    """Disjoint, exhaustive diagnostic families; omission does not remove proxies."""\n',
    '    prescribed = {\n',
    '        "recent_history": "change_mou change_rev avg3mou avg3qty avg3rev avg6mou avg6qty "\n',
    '                          "avg6rev usage_recent_to_lifetime usage_three_to_six_months "\n',
    '                          "revenue_recent_to_lifetime revenue_three_to_six_months "\n',
    '                          "usage_change_scaled revenue_change_scaled",\n',
    '        "billing_revenue": "rev_Mean totmrc_Mean da_Mean ovrrev_Mean vceovr_Mean datovr_Mean "\n',
    '                           "roam_Mean totrev adjrev avgrev overage_charge_share recurring_charge_share",\n',
    '        "usage_volume": "mou_Mean ovrmou_Mean totmou adjmou avgmou",\n',
    '        "care": "custcare_Mean ccrndmou_Mean cc_mou_Mean care_calls_per_100_attempts",\n',
    '        "equipment": "new_cell dualband refurb_new hnd_price phones models hnd_webcap "\n',
    '                     "eqpdays equipment_age_invalid equipment_age_to_tenure",\n',
    '        "tenure_household": "months uniqsubs actvsubs inactive_household_lines",\n',
    '    }\n',
    '    families = {name: tuple(c for c in columns.split() if c in features)\n',
    '                for name, columns in prescribed.items()}\n',
    '    assigned = [c for columns in families.values() for c in columns]\n',
    '    families["calls_network"] = tuple(c for c in features if c not in assigned)\n',
    '    flattened = [c for columns in families.values() for c in columns]\n',
    '    assert len(flattened) == len(set(flattened)) == len(features)\n',
    '    return families\n',
    '\n',
    '\n',
    'class Runner:\n',
    '    def __init__(self, data, store, smoke=False):\n',
    '        self.data, self.store, self.smoke = data, store, smoke\n',
    '        self.y = data.churn.to_numpy(dtype=int)\n',
    '        self.started = time.perf_counter()\n',
    '        self.new_fits, self.cache_hits = 0, 0\n',
    '\n',
    '    def progress(self, phase, fold=None, **extra):\n',
    '        self.store.json("progress.json", dict(phase=phase,\n',
    '                        fold=fold.tag if fold else None, new_fits=self.new_fits,\n',
    '                        cache_hits=self.cache_hits, current_session_seconds=time.perf_counter() - self.started,\n',
    '                        decision_allowed=not self.smoke, **extra))\n',
    '\n',
    '    def fit(self, train, predict, recipe, tag, want_training=False, resubstitution=False):\n',
    '        train, predict = np.asarray(train), np.asarray(predict)\n',
    '        if (np.intersect1d(train, predict).size and not resubstitution):\n',
    '            raise AssertionError("Held-out fit prediction request overlaps fitting rows")\n',
    '        if recipe.sensitive and not tag.startswith("ceiling/"):\n',
    '            raise AssertionError("asl_flag/area are permitted ONLY in the diagnostic ceiling")\n',
    '        specification = model_spec(recipe.backend, self.smoke)\n',
    '        signature = dict(recipe=asdict(recipe), train_hash=_indices_hash(train),\n',
    '                         predict_hash=_indices_hash(predict), specification=specification,\n',
    '                         want_training=want_training, resubstitution=resubstitution)\n',
    '        key = _digest(signature)\n',
    '        metadata_name, prediction_name = f"cache/{key}.json", f"cache/{key}.npz"\n',
    '        if self.store.path(metadata_name).exists() and self.store.path(prediction_name).exists():\n',
    '            metadata = self.store.read_json(metadata_name)\n',
    '            if metadata["signature"] != _clean(signature):\n',
    '                raise RuntimeError("Fit cache signature mismatch")\n',
    '            with np.load(self.store.path(prediction_name), allow_pickle=False) as arrays:\n',
    '                result = {name: arrays[name].copy() for name in arrays.files}\n',
    '            if not np.isfinite(result["raw"]).all() or len(result["raw"]) != len(predict):\n',
    '                raise RuntimeError("Invalid prediction cache")\n',
    '            self.cache_hits += 1\n',
    '            return result, metadata\n',
    '        self.progress("fitting", tag=tag, recipe=asdict(recipe))\n',
    '        start = time.perf_counter()\n',
    '        X_train, X_predict, cats, statistics = design(self.data, train, predict, recipe)\n',
    '        numeric = [c for c in X_train if c not in cats]\n',
    '        if recipe.backend == "lgbm":\n',
    '            from lightgbm import LGBMClassifier\n',
    '            model = LGBMClassifier(**specification)\n',
    '        elif recipe.backend == "xgboost":\n',
    '            from xgboost import XGBClassifier\n',
    '            model = XGBClassifier(**specification)\n',
    '        elif recipe.backend == "catboost":\n',
    '            from catboost import CatBoostClassifier\n',
    '            # These medians belong to THIS fit, never a global imputer.\n',
    '            medians = X_train[numeric].median().fillna(0)\n',
    '            X_train[numeric] = X_train[numeric].fillna(medians)\n',
    '            X_predict[numeric] = X_predict[numeric].fillna(medians)\n',
    '            for c in cats:\n',
    '                X_train[c] = X_train[c].astype(object).where(X_train[c].notna(), "__UNKNOWN__").astype(str)\n',
    '                X_predict[c] = X_predict[c].astype(object).where(X_predict[c].notna(), "__UNKNOWN__").astype(str)\n',
    '            statistics["feature_statistics"]["catboost_medians"] = medians.to_dict()\n',
    '            model = CatBoostClassifier(**specification, cat_features=cats)\n',
    '        elif recipe.backend == "spline_logistic":\n',
    '            model = spline_pipeline(X_train, cats, specification, self.smoke)\n',
    '        else:\n',
    '            raise ValueError(recipe.backend)\n',
    '        sample_weight = None\n',
    '        if recipe.value_weighted:\n',
    '            if recipe.backend != "lgbm":\n',
    '                raise ValueError("The weighted challenger is fixed to LightGBM")\n',
    '            value, value_limits = common.values(self.data, train)\n',
    '            sample_weight = np.maximum(value[train], 1e-6)\n',
    '            sample_weight /= sample_weight.mean()\n',
    '            statistics["feature_statistics"]["value_weight_limits"] = value_limits\n',
    '            statistics["feature_statistics"]["value_weight_rule"] = "train-only floor/median/p99 V; "\n',
    '            statistics["feature_statistics"]["value_weight_rule"] += "max(V,1e-6), normalize mean to 1"\n',
    '        with warnings.catch_warnings(record=True) as recorded, threadpool_limits(limits=THREADS):\n',
    '            warnings.simplefilter("always", ConvergenceWarning)\n',
    '            if sample_weight is None:\n',
    '                model.fit(X_train, self.y[train])\n',
    '            else:\n',
    '                model.fit(X_train, self.y[train], sample_weight=sample_weight)\n',
    '            raw = np.asarray(model.predict_proba(X_predict)[:, 1], dtype=float)\n',
    '            result = {"raw": raw}\n',
    '            if want_training:\n',
    '                result["training_raw"] = np.asarray(model.predict_proba(X_train)[:, 1], dtype=float)\n',
    '        if recipe.backend == "spline_logistic":\n',
    '            preprocessing = model.named_steps["preprocessing"]\n',
    '            numeric_fit = preprocessing.named_transformers_["numeric"]\n',
    '            statistics["feature_statistics"]["spline_logistic"] = {\n',
    '                "imputer_medians": numeric_fit.named_steps["imputer"].statistics_,\n',
    '                "quantile_knots": numeric_fit.named_steps["spline"].quantile_knots_,\n',
    '                "knot_rule": "unique train quantiles; constants held at fitted value; cubic SplineTransformer",\n',
    '                "one_hot_categories": preprocessing.named_transformers_["category"].categories_,\n',
    '                "logistic_iterations": model.named_steps["model"].n_iter_}\n',
    '        if not all(np.isfinite(array).all() for array in result.values()):\n',
    '            raise RuntimeError("Model returned non-finite predictions")\n',
    '        metadata = dict(signature=signature, first_tag=tag, fit_n=len(train),\n',
    '                        predict_n=len(predict), seconds=time.perf_counter() - start,\n',
    '                        converged=not any(issubclass(w.category, ConvergenceWarning) for w in recorded),\n',
    '                        warnings=[str(w.message) for w in recorded], **statistics)\n',
    '        self.store.npz(prediction_name, **result)\n',
    '        self.store.json(metadata_name, metadata)  # Completion marker goes LAST.\n',
    '        self.new_fits += 1\n',
    '        return result, _clean(metadata)\n',
    '\n',
    '    def raw_pair(self, fold, recipe, tag):\n',
    '        is_baseline = recipe == Recipe()\n',
    '        outer, outer_meta = self.fit(fold.train, fold.test, recipe, tag + "/outer",\n',
    '                                    want_training=is_baseline)\n',
    '        calibration, calibration_meta = self.fit(fold.development, fold.calibration,\n',
    '                                                 recipe, tag + "/calibration")\n',
    '        return outer["raw"], calibration["raw"], outer_meta, calibration_meta\n',
    '\n',
    '    def evaluate_arrays(self, fold, name, raw, raw_calibration, recipe,\n',
    '                        baseline_tail=None, converged=True, save_oof=True, extra=None):\n',
    '        development_value, development_limits = common.values(self.data, fold.development)\n',
    '        outer_value, outer_limits = common.values(self.data, fold.train)\n',
    '        prediction = calibrated_predictions(raw_calibration, self.y[fold.calibration], raw,\n',
    '                                            development_value[fold.calibration], outer_value[fold.test])\n',
    '        metrics, own, shared = measure(fold, self.y[fold.test], raw, prediction,\n',
    '                                      outer_value[fold.test], baseline_tail)\n',
    '        metrics.update(candidate=name, converged=bool(converged and prediction["calibration_converged"]),\n',
    '                       calibration_converged=prediction["calibration_converged"],\n',
    '                       decision_allowed=not self.smoke, sensitive_diagnostic=recipe.sensitive,\n',
    '                       backend=recipe.backend, groups="|".join(recipe.groups),\n',
    '                       value_weighted=recipe.value_weighted)\n',
    '        if save_oof:\n',
    '            self.store.npz(f"oof/{name}_{fold.tag}.npz",\n',
    '                           Customer_ID=self.data.Customer_ID.iloc[fold.test].to_numpy(),\n',
    '                           y=self.y[fold.test], pool_index=fold.test, raw=raw,\n',
    '                           p_s=prediction["p_s"], p_d=prediction["p_d"],\n',
    '                           value=outer_value[fold.test],\n',
    '                           deployment_weight=common.weights(self.y[fold.test], DEPLOYMENT_PRIOR,\n',
    '                                                            population=len(fold.test)),\n',
    '                           own_tail=own, baseline_tail=shared)\n',
    '        self.store.json(f"folds/{name}_{fold.tag}_recipe.json", dict(\n',
    '            recipe=asdict(recipe), development_value_limits=development_limits,\n',
    '            outer_training_value_limits=outer_limits,\n',
    '            calibration_source="20% held-out slice of outer training fold; never original 10k",\n',
    '            threshold_source="calibrated development-fit predictions on that slice only",\n',
    '            extra=extra))\n',
    '        return metrics, own\n',
    '\n',
    '    def evaluate(self, fold, name, recipe, baseline_tail=None, save_oof=True, tag=None):\n',
    '        raw, raw_cal, outer_meta, calibration_meta = self.raw_pair(fold, recipe, tag or name)\n',
    '        metrics, mask = self.evaluate_arrays(\n',
    '            fold, name, raw, raw_cal, recipe, baseline_tail,\n',
    '            converged=outer_meta["converged"] and calibration_meta["converged"], save_oof=save_oof)\n',
    '        return metrics, mask\n',
    '\n',
    '    def baseline(self, fold):\n',
    '        return self.evaluate(fold, BASELINE_NAME, Recipe())\n',
    '\n',
    '    def checkpoint(self, phase, fold, records):\n',
    '        self.store.table(f"folds/{phase}_{fold.tag}", records)\n',
    '        self.progress(phase + "_fold_complete", fold)\n',
    '\n',
    '    def nested_screen(self, fold):\n',
    '        """Group inclusion uses inner development folds, never outer outcomes."""\n',
    '        development = fold.development\n',
    '        splitter = StratifiedKFold(INNER_FOLDS, shuffle=True, random_state=SEED)\n',
    '        inner = [(development[tr], development[te]) for tr, te in splitter.split(\n',
    '            np.zeros(len(development)), self.y[development])]\n',
    '        baseline_aucs, records, selected = [], [], []\n',
    '        for number, (train, heldout) in enumerate(inner):\n',
    '            probabilities, _ = self.fit(train, heldout, Recipe(),\n',
    '                                        f"screen/{fold.tag}/baseline/i{number}")\n',
    '            baseline_aucs.append(roc_auc_score(self.y[heldout], probabilities["raw"]))\n',
    '        for group in AVAILABLE_GROUPS:\n',
    '            differences = []\n',
    '            for number, (train, heldout) in enumerate(inner):\n',
    '                probabilities, _ = self.fit(train, heldout, Recipe(groups=(group,)),\n',
    '                                            f"screen/{fold.tag}/{group}/i{number}")\n',
    '                differences.append(float(roc_auc_score(self.y[heldout], probabilities["raw"]) -\n',
    '                                         baseline_aucs[number]))\n',
    '            positive = float(np.mean(differences)) > 0\n',
    '            if positive:\n',
    '                selected.append(group)\n',
    '            records.append(dict(group=group, inner_paired_auc_mean=float(np.mean(differences)),\n',
    '                                inner_paired_auc_differences=differences, keep=positive,\n',
    '                                reason="positive inner paired AUC" if positive else "non-positive inner paired AUC"))\n',
    '        records.append(dict(group="g2_range", keep=False, reason=GROUP_NOTES["g2_range"]["reason"]))\n',
    '        self.store.json(f"folds/nested_screen_{fold.tag}.json", dict(\n',
    '            outer_repeat=fold.repeat, outer_fold=fold.number,\n',
    '            selection_population="outer development only", development_n=len(development),\n',
    '            selected_groups=selected, records=records))\n',
    '        return tuple(selected), inner, records\n',
    '\n',
    '    def inner_oof(self, fold, inner, backend, groups):\n',
    '        development = fold.development\n',
    '        position = {int(row): i for i, row in enumerate(development)}\n',
    '        probabilities = np.full(len(development), np.nan)\n',
    '        converged = True\n',
    '        for number, (train, heldout) in enumerate(inner):\n',
    '            result, metadata = self.fit(train, heldout, Recipe(backend=backend, groups=groups),\n',
    '                                        f"blend/{fold.tag}/{backend}/i{number}")\n',
    '            converged = converged and metadata["converged"]\n',
    '            probabilities[[position[int(row)] for row in heldout]] = result["raw"]\n',
    '        assert np.isfinite(probabilities).all()\n',
    '        return probabilities, bool(converged)\n',
    '\n',
    '\n',
    'def _stratified_order(indices, y, seed):\n',
    '    """Nested prefixes, proportionally interleaved and reproducible."""\n',
    '    rng = np.random.default_rng(seed)\n',
    '    classes = [rng.permutation(indices[y[indices] == label]) for label in (0, 1)]\n',
    '    ranks = [(np.arange(len(group)) + .5) / len(group) for group in classes]\n',
    '    together = np.r_[classes[0], classes[1]]\n',
    '    return together[np.argsort(np.r_[ranks[0], ranks[1]], kind="stable")]\n',
    '\n',
    '\n',
    'def run_d1(runner, folds):\n',
    '    """Measure the frozen baseline noise before any feature/model experiments."""\n',
    '    records = []\n',
    '    for fold in folds:\n',
    '        metrics, _ = runner.baseline(fold)\n',
    '        records.append(metrics)\n',
    '        runner.checkpoint("d1", fold, [metrics])\n',
    '        runner.store.table("baseline_folds", records)\n',
    '    frame = pd.DataFrame(records)\n',
    '    interval = corrected_interval(frame.auc, frame.heldout_n / frame.train_n)\n',
    '    runner.store.table("noise_floor", [dict(\n',
    '        baseline=BASELINE_NAME, mean_auc=interval["mean"],\n',
    '        corrected_mean_auc_lower=interval["lower"], corrected_mean_auc_upper=interval["upper"],\n',
    '        fold_auc_sd=float(frame.auc.std(ddof=1)), corrected_se=interval["corrected_se"],\n',
    '        test_train_ratio=interval["test_train_ratio"], df=interval["df"],\n',
    '        repeated_fold_count=len(frame), decision_allowed=not runner.smoke,\n',
    '        interpretation="baseline variability diagnostic, NOT an unpaired challenger test; "\n',
    '                       "all model gates later use corrected intervals of paired fold differences")])\n',
    '    return records\n',
    '\n',
    '\n',
    'def run_d2(runner, folds, features):\n',
    '    learning, ablations, baselines, ceiling = [], [], [], []\n',
    '    families = feature_families(features)\n',
    '    runner.store.json("feature_families.json", dict(families=families,\n',
    '                      caveat="disjoint column omission; remaining correlated proxies are not removed"))\n',
    '    for fold in folds:\n',
    '        baseline, baseline_tail = runner.baseline(fold)\n',
    '        baselines.append(baseline)\n',
    '        order = _stratified_order(fold.train, runner.y, SEED + 2000 + fold.repeat * FOLDS + fold.number)\n',
    '        if runner.smoke:\n',
    '            sizes = [max(40, int(len(order) * fraction)) for fraction in (1 / 6, 5 / 12, 5 / 6)]\n',
    '        else:\n',
    '            sizes = [10000, 25000, 50000]\n',
    '        for count in sizes + [len(order)]:\n',
    '            train = np.sort(order[:count])\n',
    '            result, metadata = runner.fit(train, fold.test, Recipe(),\n',
    '                                          f"learning/{fold.tag}/{count}", want_training=True)\n',
    '            learning.append(dict(repeat=fold.repeat, fold=fold.number,\n',
    '                                 requested_label=f"smoke_{count}" if runner.smoke else str(count),\n',
    '                                 training_n=count, heldout_n=len(fold.test),\n',
    '                                 evaluation="outer_heldout", heldout_auc=float(roc_auc_score(\n',
    '                                     runner.y[fold.test], result["raw"])),\n',
    '                                 training_auc=float(roc_auc_score(runner.y[train], result["training_raw"])),\n',
    '                                 fit_seconds=metadata["seconds"], decision_allowed=not runner.smoke))\n',
    '        fold_ablation = []\n',
    '        for family, drop in families.items():\n',
    '            name = "without_" + family\n',
    '            metrics, _ = runner.evaluate(fold, name, Recipe(drop=drop), baseline_tail, save_oof=False)\n',
    '            metrics["family"] = family\n',
    '            ablations.append(metrics)\n',
    '            fold_ablation.append(metrics)\n',
    '        # C4 is not in the candidate pool and never flows into nested screening/blending.\n',
    '        metrics, _ = runner.evaluate(fold, "diagnostic_ceiling_asl_area", Recipe(sensitive=True),\n',
    '                                     baseline_tail, save_oof=False, tag="ceiling/asl_area")\n',
    '        ceiling.append(metrics)\n',
    '        runner.checkpoint("d2", fold, [baseline] + fold_ablation + [metrics])\n',
    '        runner.store.table("learning_curve_folds", learning)\n',
    '        runner.store.table("baseline_folds", baselines)\n',
    '        runner.store.table("ablation_folds", ablations)\n',
    '        runner.store.table("diagnostic_ceiling_folds", ceiling)\n',
    '    # This is deliberately NOT a new CV point with a fictitious 75k holdout.\n',
    '    all_rows = np.arange(len(runner.data))\n',
    '    result, metadata = runner.fit(all_rows, all_rows, Recipe(), "learning/final_training_only",\n',
    '                                  resubstitution=True)\n',
    '    learning.append(dict(repeat=-1, fold=-1, requested_label="smoke_training_only" if runner.smoke\n',
    '                         else "final_fit75k_training_only", training_n=len(all_rows), heldout_n=0,\n',
    '                         evaluation="resubstitution_training_only_NOT_HELDOUT",\n',
    '                         heldout_auc=np.nan, training_auc=float(roc_auc_score(runner.y, result["raw"])),\n',
    '                         fit_seconds=metadata["seconds"], decision_allowed=False))\n',
    '    runner.store.table("learning_curve_folds", learning)\n',
    '    summary = []\n',
    '    heldout = pd.DataFrame(learning).query("heldout_n > 0")\n',
    '    for size, group in heldout.groupby("training_n", sort=True):\n',
    '        ci = corrected_interval(group.heldout_auc, group.heldout_n / group.training_n)\n',
    '        summary.append(dict(training_n=int(size), evaluation="outer_heldout",\n',
    '                            heldout_auc_mean=ci["mean"], lower=ci["lower"], upper=ci["upper"],\n',
    '                            corrected_se=ci["corrected_se"], df=ci["df"],\n',
    '                            training_auc_mean=float(group.training_auc.mean()),\n',
    '                            decision_allowed=not runner.smoke))\n',
    '    summary.append(dict(training_n=len(all_rows), evaluation="training_only_NOT_HELDOUT",\n',
    '                        heldout_auc_mean=None, lower=None, upper=None,\n',
    '                        training_auc_mean=learning[-1]["training_auc"], decision_allowed=False))\n',
    '    runner.store.table("learning_curve_summary", summary)\n',
    '    return baselines, ablations, ceiling\n',
    '\n',
    '\n',
    'def run_d3(runner, folds):\n',
    '    results = []\n',
    '    for fold in folds:\n',
    '        _, baseline_tail = runner.baseline(fold)\n',
    '        records = []\n',
    '        for group in AVAILABLE_GROUPS:\n',
    '            metrics, _ = runner.evaluate(fold, group, Recipe(groups=(group,)), baseline_tail)\n',
    '            results.append(metrics)\n',
    '            records.append(metrics)\n',
    '        runner.checkpoint("d3", fold, records)\n',
    '        runner.store.table("feature_group_folds", results)\n',
    '    return results\n',
    '\n',
    '\n',
    'def run_d4(runner, folds):\n',
    '    results, screens, blend_rows = [], [], []\n',
    '    for fold in folds:\n',
    '        _, baseline_tail = runner.baseline(fold)\n',
    '        groups, inner, screen = runner.nested_screen(fold)\n',
    '        screens.extend(dict(repeat=fold.repeat, fold=fold.number, **record) for record in screen)\n',
    '        inner_results = [runner.inner_oof(fold, inner, backend, groups) for backend in BLEND_MODELS]\n',
    '        oof = np.column_stack([result[0] for result in inner_results])\n',
    '        inner_converged = all(result[1] for result in inner_results)\n',
    '        weights, optimizer = fit_blend(oof, runner.y[fold.development])\n',
    '        runner.store.npz(f"oof/inner_blend_training_{fold.tag}.npz",\n',
    '                         pool_index=fold.development,\n',
    '                         Customer_ID=runner.data.Customer_ID.iloc[fold.development].to_numpy(),\n',
    '                         y=runner.y[fold.development], probabilities=oof, weights=weights)\n',
    '        blend_rows.append(dict(repeat=fold.repeat, fold=fold.number,\n',
    '                               selected_groups="|".join(groups), **dict(zip(BLEND_MODELS, weights)),\n',
    '                               source="3-fold OOF inside outer development; calibration/outer labels excluded",\n',
    '                               inner_components_converged=inner_converged,\n',
    '                               optimizer_iterations=optimizer["iterations"], decision_allowed=not runner.smoke))\n',
    '        raw_outer, raw_calibration, convergence, records = [], [], [], []\n',
    '        for backend in BLEND_MODELS:\n',
    '            recipe = Recipe(backend=backend, groups=groups)\n',
    '            name = "nested_" + backend\n',
    '            raw, raw_cal, outer_meta, cal_meta = runner.raw_pair(fold, recipe, name)\n',
    '            converged = outer_meta["converged"] and cal_meta["converged"]\n',
    '            metrics, _ = runner.evaluate_arrays(fold, name, raw, raw_cal, recipe, baseline_tail,\n',
    '                                                converged=converged,\n',
    '                                                extra={"group_screen": screen})\n',
    '            results.append(metrics)\n',
    '            records.append(metrics)\n',
    '            raw_outer.append(raw)\n',
    '            raw_calibration.append(raw_cal)\n',
    '            convergence.append(converged)\n',
    '        blend_raw = blend_predict(np.column_stack(raw_outer), weights)\n',
    '        blend_cal = blend_predict(np.column_stack(raw_calibration), weights)\n',
    '        metrics, _ = runner.evaluate_arrays(fold, "nested_blend", blend_raw, blend_cal,\n',
    '                                            Recipe(backend="blend", groups=groups), baseline_tail,\n',
    '                                            converged=all(convergence) and inner_converged,\n',
    '                                            extra={"weights": dict(zip(BLEND_MODELS, weights)),\n',
    '                                                   "optimizer": optimizer, "group_screen": screen,\n',
    '                                                   "inner_components_converged": inner_converged})\n',
    '        results.append(metrics)\n',
    '        records.append(metrics)\n',
    '        metrics, _ = runner.evaluate(fold, "nested_value_weighted_lgbm",\n',
    '                                     Recipe(groups=groups, value_weighted=True), baseline_tail)\n',
    '        results.append(metrics)\n',
    '        records.append(metrics)\n',
    '        runner.checkpoint("d4", fold, records)\n',
    '        runner.store.table("model_folds", results)\n',
    '        runner.store.table("nested_group_screen", screens)\n',
    '        runner.store.table("blend_weights", blend_rows)\n',
    '    return results, screens, blend_rows\n',
    '\n',
    '\n',
    'def paired_tables(baseline_records, candidate_records):\n',
    '    baseline = pd.DataFrame(baseline_records).set_index(["repeat", "fold"])\n',
    '    summaries, paired = [], []\n',
    '    metrics = ("auc", "baseline_tail_brier", "baseline_tail_logloss", "own_tail_brier",\n',
    '               "own_tail_logloss", "weighted_value_capture", "sample_brier", "sample_logloss")\n',
    '    for candidate, group in pd.DataFrame(candidate_records).groupby("candidate", sort=True):\n',
    '        group = group.set_index(["repeat", "fold"]).sort_index()\n',
    '        if not group.index.is_unique or set(group.index) != set(baseline.index):\n',
    '            raise AssertionError("Every comparison requires all ten paired outer folds")\n',
    '        reference = baseline.loc[group.index]\n',
    '        for metric in metrics:\n',
    '            difference = group[metric].to_numpy() - reference[metric].to_numpy()\n',
    '            ratios = group.heldout_n.to_numpy() / group.train_n.to_numpy()\n',
    '            interval = corrected_interval(difference, ratios)\n',
    '            summaries.append(dict(candidate=candidate, metric=metric, **interval))\n',
    '            for i, (repeat, fold) in enumerate(group.index):\n',
    '                paired.append(dict(candidate=candidate, metric=metric, repeat=repeat, fold=fold,\n',
    '                                   baseline=float(reference.iloc[i][metric]),\n',
    '                                   challenger=float(group.iloc[i][metric]), difference=float(difference[i]),\n',
    '                                   test_train_ratio=float(ratios[i])))\n',
    '    return summaries, paired\n',
    '\n',
    '\n',
    'def gate_tables(intervals, candidate_records, smoke=False):\n',
    '    by_key = {(row["candidate"], row["metric"]): row for row in intervals}\n',
    '    frame = pd.DataFrame(candidate_records)\n',
    '    gates = []\n',
    '    for name, group in frame.groupby("candidate", sort=True):\n',
    '        auc = by_key[(name, "auc")]\n',
    '        complete = len(group) == REPEATS * FOLDS and auc["complete"]\n',
    '        gain = complete and auc["mean"] >= .001 and auc["lower"] > 0\n',
    '        tail_metrics = ("baseline_tail_brier", "baseline_tail_logloss", "own_tail_brier", "own_tail_logloss")\n',
    '        tail = all(by_key[(name, metric)]["complete"] and\n',
    '                   by_key[(name, metric)]["upper"] <= 0 for metric in tail_metrics)\n',
    '        converged = bool(group.converged.all())\n',
    '        value = by_key[(name, "weighted_value_capture")]\n',
    '        weighted_challenger = name == "nested_value_weighted_lgbm"\n',
    '        # Additional conservative business gate for the explicitly value-weighted challenger.\n',
    '        value_gate = (not weighted_challenger or\n',
    '                      (value["complete"] and value["mean"] > 0 and value["lower"] > 0))\n',
    '        eligible = not bool(group.sensitive_diagnostic.any()) and not name.startswith("without_")\n',
    '        reasons = []\n',
    '        for condition, reason in ((complete, "incomplete paired folds"), (gain, "AUC mean/CI gate failed"),\n',
    '                                  (tail, "weighted tail non-degradation not established"),\n',
    '                                  (converged, "model convergence warning"),\n',
    '                                  (value_gate, "weighted value-capture improvement not established"),\n',
    '                                  (eligible, "diagnostic only"), (not smoke, "smoke is non-decision")):\n',
    '            if not condition:\n',
    '                reasons.append(reason)\n',
    '        gates.append(dict(candidate=name, eligible=eligible, mean_auc_gain=auc["mean"],\n',
    '                          corrected_auc_lower=auc["lower"], corrected_auc_upper=auc["upper"],\n',
    '                          auc_gate=bool(gain), weighted_tail_gate=bool(tail),\n',
    '                          converged=converged, value_gate=bool(value_gate),\n',
    '                          mean_weighted_value_capture_gain=value["mean"],\n',
    '                          corrected_value_capture_lower=value["lower"],\n',
    '                          pass_gate_d=bool(complete and gain and tail and converged and value_gate and eligible and not smoke),\n',
    '                          decision_allowed=not smoke, reason="; ".join(reasons) or "all preregistered gates passed"))\n',
    '    return gates\n',
    '\n',
    '\n',
    'def summarize_groups(intervals, smoke):\n',
    '    rows = []\n',
    '    for group in GROUPS:\n',
    '        if group not in AVAILABLE_GROUPS:\n',
    '            rows.append(dict(group=group, available=False, keep=False, decision_allowed=False,\n',
    '                             reason=GROUP_NOTES[group]["reason"]))\n',
    '            continue\n',
    '        ci = next(row for row in intervals if row["candidate"] == group and row["metric"] == "auc")\n',
    '        positive = ci["complete"] and ci["mean"] > 0\n',
    '        rows.append(dict(group=group, available=True, mean_auc_gain=ci["mean"],\n',
    '                         corrected_lower=ci["lower"], corrected_upper=ci["upper"],\n',
    '                         keep=bool(positive and not smoke), positive_cv_signal=bool(positive),\n',
    '                         decision_allowed=not smoke,\n',
    '                         reason="positive paired CV signal, not automatic promotion" if positive\n',
    '                         else "rejected: non-positive paired CV improvement",\n',
    '                         caveat="global diagnostic summary; nested candidates select inside each outer train"))\n',
    '    return rows\n',
    '\n',
    '\n',
    'def selected_recipe(gates, features, screens, smoke):\n',
    '    passing = [row for row in gates if row["pass_gate_d"]]\n',
    '    # Fixed tie break: greatest corrected lower bound, greatest mean gain, name.\n',
    '    passing.sort(key=lambda row: (-row["corrected_auc_lower"], -row["mean_auc_gain"], row["candidate"]))\n',
    '    selected = passing[0]["candidate"] if passing else BASELINE_NAME\n',
    '    groups = (selected,) if selected in AVAILABLE_GROUPS else ()\n',
    '    nested = selected.startswith("nested_")\n',
    '    backend = (selected.removeprefix("nested_") if nested else "lgbm")\n',
    '    if backend == "value_weighted_lgbm":\n',
    '        backend = "lgbm"\n',
    '    per_fold = [{"repeat": r["repeat"], "fold": r["fold"], "group": r["group"], "keep": r["keep"]}\n',
    '                for r in screens]\n',
    '    return dict(selected_candidate=selected, gate_d_passed=bool(passing), decision_allowed=not smoke,\n',
    '                baseline_retained=not bool(passing), base_features=features,\n',
    '                selected_feature_groups=list(groups) if not nested else "training-local selection algorithm",\n',
    '                feature_selection=("On final non-test fitting population, make fixed stratified 80/20 "\n',
    '                                   "development/calibration split, screen each available group by 3-fold "\n',
    '                                   "paired OOF AUC on development, retain positive means, then fit with "\n',
    '                                   "that set. Do not use the globally screened group list as a fixed "\n',
    '                                   "feature set: the evaluated recipe is this nested selection algorithm."\n',
    '                                   if nested else "fixed baseline plus listed singleton group, if any"),\n',
    '                outer_fold_feature_selections=per_fold if nested else [],\n',
    '                sensitive_features_deployable=False, unavailable_group="g2_range",\n',
    '                backend=backend, model_specs=MODEL_SPECS,\n',
    '                blend_components=list(BLEND_MODELS) if backend == "blend" else [],\n',
    '                blend_rule="nonnegative sum-to-one log-odds weights, fit using development inner-OOF only",\n',
    '                weighted_training=selected == "nested_value_weighted_lgbm",\n',
    '                calibration="fixed sigmoid on development-fit predictions for internal held-out calibration",\n',
    '                value_rule="train-only nonnegative recurring value, median missing fill, p99 clipping",\n',
    '                threshold_rule="prior-shifted risk*value; weighted10% cutoff from internal held-out calibration",\n',
    '                final_refit_owner="Main; this workstream never scores original calibration_policy/test",\n',
    '                final_refit_required=bool(passing),\n',
    '                learning_curve_75k="baseline training-only diagnostic; not a production model artifact",\n',
    '                selection_caveat="Gate D intervals are conservative paired, pointwise exploratory intervals, "\n',
    '                                 "not simultaneous post-model-selection confidence guarantees")\n',
    '\n',
    '\n',
    'def export_selected_oof(runner, selected, folds):\n',
    '    records = []\n',
    '    for fold in folds:\n',
    '        with np.load(runner.store.path(f"oof/{selected}_{fold.tag}.npz"), allow_pickle=False) as arrays:\n',
    '            frame = pd.DataFrame({key: arrays[key] for key in\n',
    '                                  ("Customer_ID", "pool_index", "y", "raw", "p_s", "p_d", "value")})\n',
    '        frame["repeat"], frame["fold"] = fold.repeat, fold.number\n',
    '        records.append(frame)\n',
    '    frame = pd.concat(records, ignore_index=True).sort_values(["repeat", "pool_index"])\n',
    '    coverage = frame.groupby(["repeat", "pool_index"]).size()\n',
    '    assert len(frame) == REPEATS * len(runner.data) and (coverage == 1).all()\n',
    '    runner.store.table("selected_oof_repeated", frame)\n',
    '    mean = frame.groupby(["pool_index", "Customer_ID", "y"], as_index=False)[["raw", "p_s", "p_d", "value"]].mean()\n',
    '    mean["n_repeats"] = REPEATS\n',
    '    mean["purpose"] = "non-test cross-fitted predictions; averaging repeats is not extra independent data"\n',
    '    runner.store.table("selected_oof_mean", mean)\n',
    '\n',
    '\n',
    'def package_versions():\n',
    '    return {name: importlib.metadata.version(name) for name in\n',
    '            ("numpy", "pandas", "scipy", "scikit-learn", "lightgbm", "catboost", "xgboost", "threadpoolctl")}\n',
    '\n',
    '\n',
    'def validate_environment():\n',
    '    actual = Path(sys.executable).resolve()\n',
    '    if os.path.normcase(str(actual)) != os.path.normcase(str(SHARED_PYTHON.resolve())):\n',
    '        raise RuntimeError(f"Use only the shared interpreter: {SHARED_PYTHON}")\n',
    '    if SEED != 20261028 or THREADS != 6:\n',
    '        raise AssertionError("common must retain SEED=20261028 and six CPU threads")\n',
    '    selection = json.loads((common.ROOT / "v1_frozen/analysis_outputs/model_selection.json").read_text(encoding="utf-8"))\n',
    '    if selection["iterations"] != 385 or selection["selected_model"] != "LightGBM wider leaves":\n',
    '        raise AssertionError("Frozen baseline provenance changed")\n',
    '    return package_versions()\n',
    '\n',
    '\n',
    'def run(smoke=False, output=None):\n',
    '    versions = validate_environment()  # No downloads or dependency installation.\n',
    '    data, partitions = common.load_data()\n',
    '    pool = non_test_pool(data, partitions)\n',
    '    del data, partitions\n',
    '    if smoke:\n',
    '        chosen, _ = train_test_split(np.arange(len(pool)), train_size=SMOKE_ROWS,\n',
    '                                     stratify=pool.churn, random_state=SEED)\n',
    '        pool = pool.iloc[np.sort(chosen)].reset_index(drop=True)\n',
    '    folds = list(outer_folds(pool.churn))\n',
    '    source = pool.drop(columns="_original_partition")\n',
    '    X, _ = common.operational_features(source, folds[0].train)\n',
    '    features = X.columns.tolist()\n',
    '    del X\n',
    '    frozen_manifest = json.loads((common.ROOT / "v1_frozen/analysis_outputs/feature_manifest.json").read_text(encoding="utf-8"))\n',
    '    if features != frozen_manifest["features"]:\n',
    '        raise AssertionError("The baseline feature list differs from the frozen manifest")\n',
    '    paths = [Path(__file__), Path(common.__file__),\n',
    '             common.ROOT / "v1_frozen/analysis_pipeline.py",\n',
    '             common.ROOT / "v1_frozen/analysis_outputs/model_selection.json",\n',
    '             common.ROOT / "v1_frozen/analysis_outputs/feature_manifest.json",\n',
    '             common.ROOT / "v1_frozen/analysis_outputs/tables/split_manifest.csv"]\n',
    '    input_hash = hashlib.sha256(pd.util.hash_pandas_object(pool, index=True).values.tobytes()).hexdigest()\n',
    '    metadata = dict(schema_version=1, seed=SEED, cpu_threads=THREADS, interpreter=str(SHARED_PYTHON),\n',
    '                    smoke=smoke, decision_allowed=not smoke, input_rows=len(pool), input_hash=input_hash,\n',
    '                    source_hashes={str(path): _file_hash(path) for path in paths}, versions=versions,\n',
    '                    outer_repeats=REPEATS, outer_folds=FOLDS, inner_folds=INNER_FOLDS,\n',
    '                    model_specs={name: model_spec(name, smoke) for name in BLEND_MODELS},\n',
    '                    calibration_fraction=.2, contact_share=CONTACT_SHARE,\n',
    '                    deployment_prior=DEPLOYMENT_PRIOR, group_notes=GROUP_NOTES,\n',
    '                    interval="corrected t: variance*(1/10+outer test/train=.25), conservative df=4",\n',
    '                    primary_auc="raw-score sample ROC AUC; calibrated AUC reported separately",\n',
    '                    primary_tail="Brier/logloss of prior-shifted probabilities on outcome-reweighted "\n',
    '                                 "outer samples in the baseline-defined nominal weighted10% tail; "\n',
    '                                 "cutoff comes ONLY from the outer-training internal calibration slice",\n',
    '                    tail_gate="corrected 95% upper<=0 for paired Brier/logloss degradation on "\n',
    '                              "baseline-fixed AND own-policy tails; no noninferiority margin",\n',
    '                    restricted_rows="exact original train+validation only; no original 10k/15k decisions",\n',
    '                    execution="sequential CPU; fixed specs, no sweeps; predictions cached, models not persisted")\n',
    '    default = common.WORK / ("d_smoke" if smoke else "d_results")\n',
    '    store = Artifacts(Path(output) if output else default)\n',
    '    store.bind(metadata)\n',
    '    store.json("feature_hypotheses.json", GROUP_NOTES)\n',
    '    manifest = []\n',
    '    for fold in folds:\n',
    '        for kind, rows in (("outer_test", fold.test), ("development", fold.development),\n',
    '                           ("inner_calibration", fold.calibration)):\n',
    '            manifest.append(pd.DataFrame({"Customer_ID": pool.Customer_ID.iloc[rows].to_numpy(),\n',
    '                                          "pool_index": rows, "repeat": fold.repeat,\n',
    '                                          "fold": fold.number, "role": kind,\n',
    '                                          "original_partition": pool._original_partition.iloc[rows].to_numpy()}))\n',
    '    store.table("cv_manifest", pd.concat(manifest, ignore_index=True))\n',
    '    runner = Runner(pool, store, smoke)\n',
    '    try:\n',
    '        with threadpool_limits(limits=THREADS):\n',
    '            run_d1(runner, folds)\n',
    '            baselines, ablations, ceiling = run_d2(runner, folds, features)\n',
    '            groups = run_d3(runner, folds)\n',
    '            group_intervals, _ = paired_tables(baselines, groups)\n',
    '            store.table("feature_group_intervals", group_intervals)\n',
    '            store.table("feature_group_decisions", summarize_groups(group_intervals, smoke))\n',
    '            models, screens, weights = run_d4(runner, folds)\n',
    '        candidates = groups + models\n',
    '        intervals, paired = paired_tables(baselines, candidates + ablations + ceiling)\n',
    '        gates = gate_tables(intervals, candidates, smoke)\n',
    '        group_summary = summarize_groups(intervals, smoke)\n',
    '        store.table("all_fold_metrics", baselines + candidates + ablations + ceiling)\n',
    '        store.table("paired_fold_differences", paired)\n',
    '        store.table("paired_corrected_intervals", intervals)\n',
    '        store.table("feature_group_decisions", group_summary)\n',
    '        store.table("gate_d", gates)\n',
    '        ablation_ci = [row for row in intervals if row["candidate"].startswith("without_")]\n',
    '        ceiling_ci = [row for row in intervals if row["candidate"].startswith("diagnostic_ceiling_")]\n',
    '        store.table("ablation_summary", ablation_ci)\n',
    '        store.table("diagnostic_ceiling_summary", ceiling_ci)\n',
    '        recipe = selected_recipe(gates, features, screens, smoke)\n',
    '        # Exact feature names, vocabularies and feature statistics are also persisted per fit.\n',
    '        feature_catalog = {}\n',
    '        for group in AVAILABLE_GROUPS:\n',
    '            _, _, _, statistics = design(pool, folds[0].train, folds[0].test, Recipe(groups=(group,)))\n',
    '            feature_catalog[group] = [c for c in statistics["features"] if c not in features]\n',
    '        recipe["optional_feature_catalog"] = feature_catalog\n',
    '        if recipe["selected_candidate"].startswith("nested_"):\n',
    '            recipe["selected_features_by_outer_fold"] = [dict(\n',
    '                repeat=fold.repeat, fold=fold.number,\n',
    '                features=features + [column for record in screens\n',
    '                    if record["repeat"] == fold.repeat and record["fold"] == fold.number\n',
    '                    and record["keep"] for column in feature_catalog[record["group"]]])\n',
    '                for fold in folds]\n',
    '            recipe["selected_features"] = "training-local; see per-fold lists and final feature-selection rule"\n',
    '        else:\n',
    '            recipe["selected_features"] = features + [column\n',
    '                for group in recipe["selected_feature_groups"] for column in feature_catalog[group]]\n',
    '        store.json("selected_model_recipe.json", recipe)\n',
    '        if recipe["gate_d_passed"]:\n',
    '            export_selected_oof(runner, recipe["selected_candidate"], folds)\n',
    '        fit_metadata = [json.loads(path.read_text(encoding="utf-8"))\n',
    '                        for path in store.path("cache").glob("*.json")]\n',
    '        runtime = dict(current_session_seconds=time.perf_counter() - runner.started,\n',
    '                       cumulative_completed_fit_seconds=sum(row["seconds"] for row in fit_metadata),\n',
    '                       completed_unique_fits=len(fit_metadata), new_fits=runner.new_fits,\n',
    '                       cache_hits=runner.cache_hits, execution="sequential; six CPU threads per fit",\n',
    '                       decision_allowed=not smoke)\n',
    '        store.table("fit_runtime", [dict(tag=row["first_tag"], fit_n=row["fit_n"],\n',
    '                    predict_n=row["predict_n"], seconds=row["seconds"], converged=row["converged"],\n',
    '                    backend=row["signature"]["recipe"]["backend"],\n',
    '                    groups="|".join(row["signature"]["recipe"]["groups"]),\n',
    '                    sensitive_diagnostic=row["signature"]["recipe"]["sensitive"],\n',
    '                    decision_allowed=not smoke) for row in fit_metadata])\n',
    '        store.table("runtime_table", [runtime])\n',
    '        store.json("runtime.json", runtime)\n',
    '        store.json("summary.json", dict(status="complete", decision_allowed=not smoke,\n',
    '                   gate_d_passed=recipe["gate_d_passed"], selected_candidate=recipe["selected_candidate"],\n',
    '                   original_calibration_policy_rows_used=0, original_test_rows_used=0,\n',
    '                   repeated_oof_rows=REPEATS * len(pool), runtime=runtime,\n',
    '                   issues=[GROUP_NOTES["g2_range"]["reason"], GROUP_NOTES["g1_temporal"]["window_caveat"],\n',
    '                           "Final refit/test scoring belongs to Main, conditional on Gate D.",\n',
    '                           "Training-only 75k baseline learning point is not held-out evidence.",\n',
    '                           "Corrected intervals are exploratory pointwise, not selection-adjusted.",\n',
    '                           "48k calibration-source fit versus 60k outer refit can shift calibration."]))\n',
    '        runner.progress("complete", selected_candidate=recipe["selected_candidate"],\n',
    '                        gate_d_passed=recipe["gate_d_passed"])\n',
    '        return recipe\n',
    '    except Exception as error:\n',
    '        runner.progress("interrupted_or_failed", error_type=type(error).__name__, error=str(error),\n',
    '                        recovery="Rerun the identical command; completed atomic fit caches are reused")\n',
    '        raise\n',
    '\n',
    '\n',
    'def main(argv=None):\n',
    '    parser = argparse.ArgumentParser(description=__doc__)\n',
    '    modes = parser.add_mutually_exclusive_group(required=True)\n',
    '    modes.add_argument("--run", action="store_true", help="Full non-test 2x5 repeated CV; no locked-test scoring")\n',
    '    modes.add_argument("--smoke", action="store_true", help="All stages on 1000 original non-test rows; NON-DECISION")\n',
    '    parser.add_argument("--output-dir", type=Path, help="Dedicated child of v2_work; default d_results/d_smoke")\n',
    '    args = parser.parse_args(argv)\n',
    '    return run(smoke=args.smoke, output=args.output_dir)\n',
    '\n',
    '\n',
    'if __name__ == "__main__":\n',
    '    main()\n'
]))

# %% V2 module a_budget_gate
_v2_materialize('a_budget_gate', ''.join([
    'import json\n',
    'import numpy as np\n',
    'import pandas as pd\n',
    'from common import WORK, SEED, dump\n',
    'from workstream_a import scores, fit_thresholds, measure\n',
    '\n',
    "spec=json.loads((WORK/'a_spec.json').read_text())\n",
    "cal=pd.read_csv(WORK/'a_selected_calibration.csv')\n",
    "cal['p_s']=cal.p_s_oof\n",
    'rng=np.random.default_rng(SEED+180)\n',
    'rows=[]\n',
    "for choice in spec['optimal_budgets_calibration_only']:\n",
    "    cost,fraction=choice['cost'],choice['fraction']\n",
    '    thresholds=fit_thresholds(cal,fraction=fraction,cost=cost)\n',
    '    benchmark=fit_thresholds(cal,fraction=.1,cost=cost)\n',
    "    sc=scores(cal)['bayes']\n",
    "    candidate=sc>=thresholds['bayes']\n",
    "    baseline=sc>=benchmark['bayes']\n",
    '    bootstrap=[]\n',
    '    for _ in range(300):\n',
    '        ix=rng.integers(0,len(cal),len(cal))\n',
    '        frame=cal.iloc[ix].reset_index(drop=True)\n',
    "        bootstrap.append(measure(frame,candidate[ix],cost=cost)['net']-measure(frame,baseline[ix],cost=cost)['net'])\n",
    '    lower,upper=np.quantile(bootstrap,[.025,.975])\n',
    "    difference=measure(cal,candidate,cost=cost)['net']-measure(cal,baseline,cost=cost)['net']\n",
    "    rows.append({'cost':cost,'calibration_selected_fraction':fraction,'paired_net_gain_vs10':difference,'ci_lower':lower,'ci_upper':upper,'positive_net_under_assumptions':choice['launch_allowed_by_assumed_calibration_net'],'exploratory_conditional_interval_excludes0':lower>0,'eligible_for_headline_promotion':False,'reason':'Fraction optimized on same policy-calibration support; conditional interval omits search uncertainty. Retain predeclared10% headline; prospective experiment determines campaign size. Include no-contact option with0 net; grid endpoints are constrained optima.'})\n",
    "pd.DataFrame(rows).to_csv(WORK/'a_budget_gate.csv',index=False)\n",
    "spec['budget_gate']=rows\n",
    "spec['promoted_headline_fraction']=.1\n",
    "dump('a_spec.json',spec)\n",
    "print(pd.DataFrame(rows)[['cost','calibration_selected_fraction','paired_net_gain_vs10','ci_lower','ci_upper']].to_string(index=False))\n"
]))

# %% V2 module headroom_refit
_v2_materialize('headroom_refit', ''.join([
    'from dataclasses import asdict\n',
    'from hashlib import sha256\n',
    'import json\n',
    'from pathlib import Path\n',
    '\n',
    'import joblib\n',
    'import numpy as np\n',
    'import pandas as pd\n',
    'from scipy.special import logit\n',
    'from sklearn.model_selection import train_test_split\n',
    '\n',
    'import common\n',
    'import workstream_d as d\n',
    '\n',
    '\n',
    'ROOT, WORK = common.ROOT, common.WORK\n',
    '\n',
    '\n',
    'def fit_backend(X, y, cats, backend, weight=None):\n',
    '    specification = d.model_spec(backend)\n',
    '    medians = None\n',
    "    if backend == 'lgbm':\n",
    '        from lightgbm import LGBMClassifier\n',
    '        model = LGBMClassifier(**specification)\n',
    "    elif backend == 'xgboost':\n",
    '        from xgboost import XGBClassifier\n',
    '        model = XGBClassifier(**specification)\n',
    "    elif backend == 'catboost':\n",
    '        from catboost import CatBoostClassifier\n',
    '        numeric = [c for c in X if c not in cats]\n',
    '        medians = X[numeric].median().fillna(0)\n',
    '        X = catboost_inputs(X, cats, medians)\n',
    '        model = CatBoostClassifier(**specification, cat_features=cats)\n',
    "    elif backend == 'spline_logistic':\n",
    '        model = d.spline_pipeline(X, cats, specification)\n',
    '    else:\n',
    '        raise ValueError(backend)\n',
    '    import warnings\n',
    '    from sklearn.exceptions import ConvergenceWarning\n',
    '    with warnings.catch_warnings(record=True) as recorded:\n',
    "        warnings.simplefilter('always', ConvergenceWarning)\n",
    '        if weight is None:\n',
    '            model.fit(X, y)\n',
    '        else:\n',
    '            model.fit(X, y, sample_weight=weight)\n',
    "    assert not any(issubclass(item.category, ConvergenceWarning) for item in recorded), 'Final refit did not converge.'\n",
    '    return model, medians\n',
    '\n',
    '\n',
    'def catboost_inputs(X, cats, medians):\n',
    '    X = X.copy()\n',
    '    X[medians.index] = X[medians.index].fillna(medians)\n',
    '    for column in cats:\n',
    "        X[column] = X[column].astype(object).where(X[column].notna(), '__UNKNOWN__').astype(str)\n",
    '    return X\n',
    '\n',
    '\n',
    'def prepare():\n',
    "    recipe_path = WORK / 'd_results/selected_model_recipe.json'\n",
    "    selected = json.loads(recipe_path.read_text(encoding='utf-8'))\n",
    "    assert selected['gate_d_passed'] and selected['decision_allowed']\n",
    "    assert not (WORK / 'final_frozen_protocol.json').exists()\n",
    "    assert not (WORK / 'a_selected_test.csv').exists()\n",
    "    target = WORK / 'd_promoted_model.joblib'\n",
    "    assert not target.exists(), 'Do not repeat a completed production refit.'\n",
    '    data, splits = common.load_data()\n',
    "    train = np.r_[splits['train'], splits['validation']]\n",
    '    pool = d.non_test_pool(data, splits)\n',
    '    development, calibration = train_test_split(np.arange(len(pool)), test_size=.2,\n',
    '        stratify=pool.churn, random_state=common.SEED + 3000)\n',
    "    groups = tuple(selected['selected_feature_groups']) if not selected['selected_candidate'].startswith('nested_') else ()\n",
    '    blend_weights = None\n',
    "    if selected['selected_candidate'].startswith('nested_'):\n",
    "        store = d.Artifacts(WORK / 'd_final_screen')\n",
    "        store.bind({'recipe_sha256': sha256(recipe_path.read_bytes()).hexdigest(),\n",
    "                    'seed': common.SEED + 3000, 'rows': 75000, 'test_rows_used': 0})\n",
    '        runner = d.Runner(pool, store)\n',
    '        fold = d.Fold(0, 0, np.arange(len(pool)), np.array([], dtype=int),\n',
    '                      np.sort(development), np.sort(calibration))\n',
    '        groups, inner, screen = runner.nested_screen(fold)\n',
    "        if selected['backend'] == 'blend':\n",
    '            oof = np.column_stack([runner.inner_oof(fold, inner, backend, groups)\n',
    '                                   for backend in d.BLEND_MODELS])\n',
    '            blend_weights, optimizer = d.fit_blend(oof, pool.churn.iloc[fold.development])\n',
    "            store.json('final_blend_spec.json', {'weights': blend_weights, 'optimizer': optimizer,\n",
    "                                                'groups': groups, 'screen': screen})\n",
    "    components = d.BLEND_MODELS if selected['backend'] == 'blend' else (selected['backend'],)\n",
    '    fitted = []\n',
    '    for backend in components:\n',
    '        recipe = d.Recipe(backend=backend, groups=groups,\n',
    "                          value_weighted=selected['weighted_training'])\n",
    "        X, _, cats, statistics = d.design(data, train, splits['calibration_policy'], recipe)\n",
    '        weight = None\n',
    '        if recipe.value_weighted:\n',
    '            value, _ = common.values(data, train)\n',
    '            weight = np.maximum(value[train], 1e-6)\n',
    '            weight /= weight.mean()\n',
    '        model, medians = fit_backend(X, data.churn.iloc[train].to_numpy(), cats, backend, weight)\n',
    "        fitted.append({'model': model, 'recipe': asdict(recipe), 'cats': cats,\n",
    "                       'catboost_medians': medians, 'statistics': statistics})\n",
    "    bundle = {'selected_candidate': selected['selected_candidate'], 'train_indices': train,\n",
    "              'components': fitted, 'blend_weights': blend_weights,\n",
    "              'test_scored': False, 'recipe_sha256': sha256(recipe_path.read_bytes()).hexdigest()}\n",
    '    joblib.dump(bundle, target)\n',
    "    common.dump('d_promoted_refit.json', {'candidate': bundle['selected_candidate'],\n",
    "                'training_rows': len(train), 'groups': groups, 'test_rows_used': 0,\n",
    "                'model_sha256': sha256(target.read_bytes()).hexdigest(),\n",
    "                'value_proxy_limits_source': 'Original 60000 train for comparable policy valuation; model weights use final fitting rows.',\n",
    "                'feature_statistics': [row['statistics'] for row in fitted]})\n",
    '    return bundle\n',
    '\n',
    '\n',
    'def raw_predict(data, indices):\n',
    "    bundle = joblib.load(WORK / 'd_promoted_model.joblib')\n",
    '    outputs = []\n',
    "    for component in bundle['components']:\n",
    "        spec = component['recipe'].copy()\n",
    "        spec['groups'], spec['drop'] = tuple(spec['groups']), tuple(spec['drop'])\n",
    '        recipe = d.Recipe(**spec)\n',
    "        _, X, cats, statistics = d.design(data, bundle['train_indices'], indices, recipe)\n",
    "        assert d._clean(statistics) == d._clean(component['statistics'])\n",
    "        if recipe.backend == 'catboost':\n",
    "            X = catboost_inputs(X, cats, component['catboost_medians'])\n",
    "        outputs.append(component['model'].predict_proba(X)[:, 1])\n",
    "    raw = d.blend_predict(np.column_stack(outputs), bundle['blend_weights']) if bundle['blend_weights'] is not None else outputs[0]\n",
    '    assert np.isfinite(raw).all()\n',
    '    return raw\n',
    '\n',
    '\n',
    "def calibration_predictions(partition='calibration_policy'):\n",
    "    assert partition == 'calibration_policy'\n",
    '    data, splits = common.load_data()\n',
    '    indices = splits[partition]\n',
    '    raw = raw_predict(data, indices)\n',
    "    value, _ = common.values(data, splits['train'])\n",
    "    frame = pd.DataFrame({'Customer_ID': data.Customer_ID.iloc[indices].to_numpy(),\n",
    "                          'y': data.churn.iloc[indices].to_numpy(), 'p_raw': raw,\n",
    "                          'p_s': raw, 'p_d': common.shift(raw), 'value': value[indices],\n",
    "                          'weight': common.weights(data.churn.iloc[indices].to_numpy()),\n",
    "                          'partition': partition})\n",
    '    return data, splits, frame\n',
    '\n',
    '\n',
    'def evaluate_test():\n',
    '    import workstream_a as a\n',
    '    from final_protocol import begin_test\n',
    '    begin_test(promoted=True)\n',
    '    data, splits = common.load_data()\n',
    "    indices = splits['test']\n",
    '    raw = raw_predict(data, indices)\n',
    "    calibrator = joblib.load(WORK / 'a_calibrator.joblib')\n",
    '    probability = calibrator.predict(raw)\n',
    "    value, _ = common.values(data, splits['train'])\n",
    "    frame = pd.DataFrame({'Customer_ID': data.Customer_ID.iloc[indices].to_numpy(),\n",
    "                          'y': data.churn.iloc[indices].to_numpy(), 'p_raw': raw,\n",
    "                          'p_s': probability, 'p_d': common.shift(probability),\n",
    "                          'value': value[indices], 'weight': common.weights(data.churn.iloc[indices].to_numpy()),\n",
    "                          'partition': 'test'})\n",
    "    spec = json.loads((WORK / 'a_spec.json').read_text(encoding='utf-8'))\n",
    '    scores = a.scores(frame)\n',
    "    frame['selected_risk'] = scores['risk'] >= spec['thresholds']['0.02']['risk']\n",
    "    frame['selected_bayes'] = scores['bayes'] >= spec['thresholds']['0.02']['bayes']\n",
    "    frame.to_csv(WORK / 'a_selected_test.csv', index=False)\n",
    "    a.analyze(pd.read_csv(WORK / 'a_selected_calibration.csv'), frame, data, splits, 'test')\n",
    '    paired_test_comparison(frame)\n',
    '    return frame\n',
    '\n',
    '\n',
    'def paired_test_comparison(frame):\n',
    '    from sklearn.metrics import roc_auc_score, log_loss, brier_score_loss, accuracy_score\n',
    '    import workstream_a as a\n',
    '\n',
    "    frozen = pd.read_csv(ROOT / 'v1_frozen/analysis_outputs/tables/heldout_predictions.csv').set_index('Customer_ID')\n",
    '    reference = frozen.loc[frame.Customer_ID]\n',
    '    y = frame.y.to_numpy()\n',
    '    assert np.array_equal(y, reference.actual_churn.to_numpy())\n',
    '    v1 = reference.sample_calibrated_churn_probability.to_numpy()\n',
    '    probability = frame.p_s.to_numpy()\n',
    '    raw = frame.p_raw.to_numpy()\n',
    '    rng = np.random.default_rng(common.SEED + 4000)\n',
    '    draws = []\n',
    '    for replicate in range(300):\n',
    '        ix = rng.integers(0, len(y), len(y))\n',
    '        baseline_auc = roc_auc_score(y[ix], v1[ix])\n',
    '        candidate_auc = roc_auc_score(y[ix], raw[ix])\n',
    "        draws.append({'replicate': replicate, 'v1_auc': baseline_auc,\n",
    "                      'v2_auc': candidate_auc, 'paired_auc_gain': candidate_auc - baseline_auc})\n",
    '    draws = pd.DataFrame(draws)\n',
    "    draws.to_csv(WORK / 'd_final_test_bootstrap.csv', index=False)\n",
    "    common.dump('d_final_test_comparison.json', {\n",
    "        'test_rows': len(frame), 'v1_test_previously_evaluated': True,\n",
    "        'decisions_frozen_before_scoring': True, 'test_used_for_selection': False,\n",
    "        'v1_auc': float(roc_auc_score(y, v1)), 'v2_auc': float(roc_auc_score(y, raw)),\n",
    "        'paired_auc_gain': float(roc_auc_score(y, raw) - roc_auc_score(y, v1)),\n",
    "        'paired_auc_gain_95ci': [float(draws.paired_auc_gain.quantile(.025)), float(draws.paired_auc_gain.quantile(.975))],\n",
    "        'v2_auc_95ci': [float(draws.v2_auc.quantile(.025)), float(draws.v2_auc.quantile(.975))],\n",
    "        'v2_calibrated_metrics': {'auc': float(roc_auc_score(y, probability)),\n",
    "                                  'log_loss': float(log_loss(y, probability)),\n",
    "                                  'brier': float(brier_score_loss(y, probability)),\n",
    "                                  'accuracy_at_half': float(accuracy_score(y, probability >= .5))},\n",
    "        'sample_top10': {name: a.sample_measure(frame, score) for name, score in a.scores(frame, prior=.4956).items()},\n",
    "        'interval_scope': '300 paired IID row resamples of the same heldout rows, conditional on locked models; no retraining, external validation or post-selection guarantee.',\n",
    "        'promotion_rule': 'Gate D non-test results determine promotion, never this heldout comparison.'})\n"
]))

# %% V2 module final_protocol
_v2_materialize('final_protocol', ''.join([
    'from hashlib import sha256\n',
    'import json\n',
    'from pathlib import Path\n',
    'from datetime import datetime, timezone\n',
    '\n',
    'from common import ROOT, WORK, SEED, THREADS\n',
    '\n',
    '\n',
    "FILES = ('a_spec.json', 'a_calibrator.joblib', 'a_selected_calibration.csv',\n",
    "         'c_proxy_cv.csv', 'd_results/selected_model_recipe.json',\n",
    "         'd_results/gate_d.json', 'd_results/run_spec.json',\n",
    "         'common.py', 'workstream_a.py', 'workstream_b.py', 'workstream_c.py',\n",
    "         'workstream_d.py', 'a_budget_gate.py', 'headroom_refit.py',\n",
    "         'final_protocol.py', 'run_frozen_batch.py', 'final_metrics.py', 'generate_visuals.py')\n",
    "BASELINE_FILES = ('v1_frozen/analysis_pipeline.py',\n",
    "                  'v1_frozen/analysis_outputs/models/selected_model.joblib',\n",
    "                  'v1_frozen/analysis_outputs/tables/split_manifest.csv',\n",
    "                  'v1_frozen/analysis_outputs/tables/heldout_predictions.csv',\n",
    "                  'v1_frozen/analysis_outputs/source_manifest.json')\n",
    '\n',
    '\n',
    'def freeze():\n',
    "    target = WORK / 'final_frozen_protocol.json'\n",
    '    if target.exists():\n',
    '        verify()\n',
    "        return json.loads(target.read_text(encoding='utf-8'))\n",
    "    d_summary = json.loads((WORK / 'd_results/summary.json').read_text(encoding='utf-8'))\n",
    "    assert d_summary['status'] == 'complete' and d_summary['decision_allowed']\n",
    "    assert d_summary['original_test_rows_used'] == 0\n",
    "    assert d_summary['original_calibration_policy_rows_used'] == 0\n",
    "    assert not (WORK / 'a_selected_test.csv').exists(), 'Freeze must precede final test evaluation.'\n",
    "    spec = json.loads((WORK / 'a_spec.json').read_text(encoding='utf-8'))\n",
    "    assert not spec['test_used_for_selection']\n",
    "    assert spec['promoted_headline_fraction'] == .1\n",
    '    paths = list(FILES)\n',
    "    if d_summary['gate_d_passed']:\n",
    "        paths.extend(['d_promoted_model.joblib', 'd_promoted_refit.json'])\n",
    "    paths.extend(p.name for p in WORK.glob('b*spec*.json'))\n",
    "    paths.extend(p.name for p in WORK.glob('b*design*.json'))\n",
    "    assert any(name.startswith('b') for name in paths), 'Pilot design must be frozen before test.'\n",
    "    originals = json.loads((ROOT / 'v1_frozen/analysis_outputs/source_manifest.json').read_text(encoding='utf-8'))\n",
    "    protected_hashes = {relative.replace('\\\\', '/'): info['sha256'] for relative, info in originals.items()}\n",
    '    assert len(protected_hashes) == 5\n',
    '    for relative, digest in protected_hashes.items():\n',
    '        assert sha256((ROOT / relative).read_bytes()).hexdigest() == digest, relative\n',
    '    baseline_hashes = {name: sha256((ROOT / name).read_bytes()).hexdigest() for name in BASELINE_FILES}\n',
    "    record = {'seed': SEED, 'threads': THREADS,\n",
    "              'frozen_utc': datetime.now(timezone.utc).isoformat(),\n",
    "              'v1_test_previously_evaluated': True, 'test_selected_decisions': False,\n",
    "              'model_candidate': d_summary['selected_candidate'],\n",
    "              'gate_d_passed': d_summary['gate_d_passed'],\n",
    "              'calibrator': spec['calibrator'], 'headline_fraction': .1,\n",
    "              'hashes': {name: sha256((WORK / name).read_bytes()).hexdigest() for name in sorted(set(paths))},\n",
    "              'baseline_hashes': baseline_hashes, 'protected_original_hashes': protected_hashes,\n",
    "              'final_test_rule': 'One frozen descriptive batch; no model, calibrator, budget, routing or pilot selection on final test. Canonical notebook replay may reuse verified results without a second decision search.',\n",
    "              'service_fix_floor': 'Remediate every verified billing/network defect irrespective of bill size or discretionary selection.',\n",
    "              'financial_assumptions': {'population': 100000, 'prior': .02, 'prevention': .2,\n",
    "                                       'retained_months': 6, 'margin': .6, 'contact_cost': 1., 'fixed_cost': 5000.}}\n",
    "    target.write_text(json.dumps(record, indent=2), encoding='utf-8')\n",
    '    return record\n',
    '\n',
    '\n',
    'def verify():\n',
    "    record = json.loads((WORK / 'final_frozen_protocol.json').read_text(encoding='utf-8'))\n",
    "    for name, digest in record['hashes'].items():\n",
    '        assert sha256((WORK / name).read_bytes()).hexdigest() == digest, name\n',
    "    for name, digest in {**record['baseline_hashes'], **record['protected_original_hashes']}.items():\n",
    '        assert sha256((ROOT / name).read_bytes()).hexdigest() == digest, name\n',
    '    return record\n',
    '\n',
    '\n',
    'def begin_test(promoted):\n',
    '    record = verify()\n',
    "    assert record['gate_d_passed'] == promoted, 'Use the frozen model route.'\n",
    "    assert not (WORK / 'a_selected_test.csv').exists(), 'Do not rescore a completed final test.'\n",
    "    with (WORK / 'final_test_started.json').open('x', encoding='utf-8') as handle:\n",
    "        json.dump({'protocol_sha256': sha256((WORK / 'final_frozen_protocol.json').read_bytes()).hexdigest(),\n",
    "                   'model_route': 'promoted' if promoted else 'v1_cached',\n",
    "                   'started_utc': datetime.now(timezone.utc).isoformat()}, handle, indent=2)\n",
    '    return record\n',
    '\n',
    '\n',
    "if __name__ == '__main__':\n",
    '    print(json.dumps(freeze(), indent=2))\n'
]))

