    'from pathlib import Path\n',
    'from hashlib import sha256\n',
    'import json\n',
    'import runpy\n',
    '\n',
    'import pandas as pd\n',
    '\n',
    'from common import ROOT, WORK, dump\n',
    'import workstream_a as a\n',
    'import workstream_b as b\n',
    'import workstream_c as c\n',
    'import workstream_d as d\n',
    'from final_protocol import freeze, verify\n',
    '\n',
    "SOURCES = ('common.py', 'workstream_a.py', 'workstream_b.py', 'workstream_c.py', 'workstream_d.py',\n",
    "           'a_budget_gate.py', 'headroom_refit.py', 'final_protocol.py', 'run_frozen_batch.py',\n",
    "           'final_metrics.py', 'generate_visuals.py')\n",
    '\n',
    '\n',
    'def fingerprints(paths):\n',
    "    return {str(path.relative_to(ROOT)).replace('\\\\', '/'): sha256(path.read_bytes()).hexdigest()\n",
    '            for path in sorted(set(paths))}\n',
    '\n',
    '\n',
    'def check_fingerprints(record):\n',
    '    for relative, digest in record.items():\n',
    '        assert sha256((ROOT / relative).read_bytes()).hexdigest() == digest, relative\n',
    '\n',
    '\n',
    'def refresh_a_spec():\n',
    "    spec = json.loads((WORK / 'a_spec.json').read_text(encoding='utf-8'))\n",
    "    summary = json.loads((WORK / 'a_summary_calibration.json').read_text(encoding='utf-8'))\n",
    "    summary['spec'] = spec\n",
    "    dump('a_summary_calibration.json', summary)\n",
    "    if not (WORK / 'a_summary_test.json').exists():\n",
    "        dump('a_summary.json', summary)\n",
    '\n',
    '\n',
    'def verify_non_test():\n',
