    "        b.main(['--partition', 'calibration'])\n",
    "        c.main(['--partition', 'calibration', '--proxy-cv', '--ceiling-results', ceiling])\n",
    '    else:\n',
    "        c.main(['--partition', 'calibration', '--bridge-only', '--ceiling-results', ceiling])\n",
    '    sources = [WORK / name for name in SOURCES]\n',
