    '\n',
    '\n',
    'def show_results():\n',
    '    verify_completed()\n',
    "    names = ('a_calibration_cv.csv', 'a_budget_gate.csv', 'a_policies_test.csv', 'a_overlap_test.csv',\n",
    "             'a_intervals_test.csv', 'a_value_proxy_sensitivity_test.csv', 'b_power_test.csv',\n",
    "             'b_queues_test.csv', 'b_cells_test.csv', 'c_proxy_cv.csv',\n",
    "             'd_results/feature_group_decisions.csv', 'd_results/gate_d.csv')\n",
    '    for name in names:\n',
    "        print('\\n' + name)\n",
