    "for (name,mask),color,marker,key in zip(regions.items(),[COLORS['teal'],COLORS['amber'],COLORS['muted']],['o','^','x'],['both','rv_only','risk_only']):\n",
    '    ix=np.flatnonzero(mask)\n',
    '    draw=ix if len(ix)<1800 else rng.choice(ix,1800,replace=False)\n',
    '    row=rows.loc[key]\n',
    '    average_risk=np.average(frame.p_d.to_numpy()[ix],weights=frame.weight.to_numpy()[ix])\n',
    "    ax.scatter(frame.p_d.to_numpy()[draw]*100,frame.value.to_numpy()[draw],s=10,alpha=.4,c=color,marker=marker,label=f'{name}: raw test n={len(ix):,}; bill {row.mean_value:.1f}; risk {average_risk:.1%}')\n",
    'x=np.linspace(.35,18,300)\n',
    "ax.plot(x,spec['thresholds']['0.02']['bayes']/(x/100),color=COLORS['ink'],lw=1.8,label='Deployment risk × value cutoff')\n",
    "ax.axvline(spec['thresholds']['0.02']['risk']*100,color=COLORS['muted'],ls='--',lw=1.2,label='_risk_cutoff')\n",
    "ax.set(xlim=(0,18),ylim=(0,125),xlabel='Assumed deployment churn risk (%)',ylabel='Monthly recurring charge (units)')\n",
    "ax.legend(loc='upper right',fontsize=9,framealpha=.95)\n",
    'fig.tight_layout()\n',
    "fig.savefig(DEST/'risk_value_tradeoff.png',bbox_inches='tight',facecolor='white')\n",
    "record_chart(fig,5,'risk_value_tradeoff.png')\n",
    'plt.close(fig)\n',
    '\n',
    'fig,ax=plt.subplots(figsize=(8,5.1))\n',
    'w=frame.weight.to_numpy();y=frame.y.to_numpy();v=frame.value.to_numpy()\n',
    "for name,score,color,style in [('Deployment risk × value',frame.p_d.to_numpy()*v,COLORS['teal'],'-'),('Risk only',frame.p_d.to_numpy(),COLORS['muted'],'--'),('Value only',v,COLORS['amber'],':')]:\n",
    "    order=np.argsort(-score,kind='stable')\n",
    '    coverage=np.cumsum(w[order])/w.sum()*100\n',
    '    gain=np.cumsum(w[order]*y[order]*v[order])/np.sum(w*y*v)*100\n',
    '    ax.plot(coverage,gain,style,color=color,lw=2,label=name)\n',
    "ax.plot([0,100],[0,100],color='#CCCCCC',ls='--',label='Random contact')\n",
    "ax.set(xlim=(0,30),ylim=(0,70),xlabel='Weighted deployment population contacted (%)',ylabel='Churned recurring value captured (%)',title='2% prior scenario; retrospective value capture')\n",
    "ax.legend(loc='lower right',fontsize=10)\n",
    'fig.tight_layout()\n',
    "fig.savefig(DEST/'value_capture_curve.png',bbox_inches='tight',facecolor='white')\n",
    "record_chart(fig,9,'value_capture_curve.png')\n",
    'plt.close(fig)\n',
    '\n',
    "curves=pd.read_csv(WORK/'a_profit_curves_test.csv')\n",
    'fig,ax=plt.subplots(figsize=(9.7,4.5))\n',
    "for cost,color,style in [(.25,COLORS['teal'],'-'),(1.,COLORS['ink'],'-'),(2.,COLORS['amber'],'--')]:\n",
